ST.xhtml:
(*Condição para retornar para zero*)
IF IHM.btGoToZero THEN
	//Posição para os eixos
	PLC.Axis[1].OperationDistance := 0;
	PLC.Axis[2].OperationDistance := 0;
	PLC.Axis[3].OperationDistance := 0;
	//Executa eixos
	PLC.Axis[1].OperationStart := TRUE;
	PLC.Axis[2].OperationStart := TRUE;
	PLC.Axis[3].OperationStart := TRUE;
	(*Condição para finalizar retorno*)
	IF PLC.Axis[1].OperationDone AND PLC.Axis[2].OperationDone AND PLC.Axis[3].OperationDone THEN
		//Desabilita execução dos eixos
		PLC.Axis[1].OperationStart := FALSE;
		PLC.Axis[2].OperationStart := FALSE;
		PLC.Axis[3].OperationStart := FALSE;
		//Desabilita condição para retorno
		IHM.btGoToZero := FALSE;
	END_IF
	(*Condição para parar retorno*)
	IF IHM.btStop THEN
		//Desabilita execução dos eixos
		PLC.Axis[1].OperationStart := FALSE;
		PLC.Axis[2].OperationStart := FALSE;
		PLC.Axis[3].OperationStart := FALSE;
		//Desabilita condição para retorno
		IHM.btGoToZero := FALSE;
	END_IF
END_IF

(*Define novo ponto zero*)
FB_Setpoint[1](Axis := Axis1, Execute := IHM.btSetPoint, Position := 0);
FB_Setpoint[2](Axis := Axis2, Execute := IHM.btSetPoint, Position := 0);
FB_Setpoint[3](Axis := Axis3, Execute := IHM.btSetPoint, Position := 0);

(*Condição para girar a serra*)
IF IHM.btRotateSaw THEN
	//Posição para o eixo
	PLC.Axis[4].OperationDistance := IHM.RotateValue;
	//Executa eixos
	PLC.Axis[4].OperationStart := TRUE;
	(*Condição para finalizar função*)
	IF PLC.Axis[4].OperationDone THEN
		//Desabilita execução dos eixos
		PLC.Axis[4].OperationStart := FALSE;
		//Desabilita condição para retorno
		IHM.btRotateSaw := FALSE;
	END_IF
	(*Condição para parar retorno*)
	IF IHM.btStop THEN
		//Desabilita execução dos eixos
		PLC.Axis[4].OperationStart := FALSE;
		//Desabilita condição para retorno
		IHM.btRotateSaw := FALSE;
	END_IF
END_IF

(*Condição para habilitar modo manual*)
IF PLC.Machine = States.Manual THEN
	(*Acionamentos manuais*)
	//Eixo X
	PLC.Axis[1].JogFwd := IHM.Axis[1].JogFwd;
	PLC.Axis[1].JogRev := IHM.Axis[1].JogRev;
	//Eixo Y
	PLC.Axis[2].JogFwd := IHM.Axis[2].JogFwd;
	PLC.Axis[2].JogRev := IHM.Axis[2].JogRev;
	//Eixo Z
	PLC.Axis[3].JogFwd := IHM.Axis[3].JogFwd;
	PLC.Axis[3].JogRev := IHM.Axis[3].JogRev;
	//Eixo W
	PLC.Axis[4].JogFwd := IHM.Axis[4].JogFwd;
	PLC.Axis[4].JogRev := IHM.Axis[4].JogRev;

	(*Definir novo ponto zero*)
	SetPoint();

	(*Retorna para ponto zero*)
	GoToZero();

	(*Girar a serra*)
	RotateSaw();
END_IF

(*Estado do homing rodando*)
Homing.Running := TRUE;
Homing.Start := FALSE;
Homing.Done := FALSE;
Homing.Abort := FALSE;
Homing.State := Homing.State + 1;

(*Estado do homing abortando*)
Homing.Running := FALSE;
Homing.Abort := TRUE;
Homing.State := 0;
PLC.FB_Homing[1].bExecute := FALSE;
PLC.FB_Homing[2].bExecute := FALSE;
PLC.FB_Homing[3].bExecute := FALSE;
PLC.FB_Homing[4].bExecute := FALSE;
IHM.btStartHome := FALSE;

(*Estado do homing abortando*)
Homing.Running := FALSE;
Homing.Done := TRUE;
Homing.State := 0;
PLC.FB_Homing[1].bExecute := FALSE;
PLC.FB_Homing[2].bExecute := FALSE;
PLC.FB_Homing[3].bExecute := FALSE;
PLC.FB_Homing[4].bExecute := FALSE;
IHM.btStartHome := FALSE;
PLC.Machine := States.Manual;

(*Condição para iniciar homing*)
IF PLC.Machine = States.Manual THEN
	IF IHM.btStartHome THEN
		Homing.Start := TRUE;
		PLC.Machine := States.Homing;
		Homing.State := 1;
	END_IF
	(*Condição para parar homing*)
	ELSIF PLC.Machine = States.Homing THEN
		IF IHM.btStop THEN
			PLC.Machine := States.Manual;
			Homing.State := 999;
		END_IF
END_IF

(*Rotina de Homing*)
CASE Homing.State OF
	1: //Estado rodando
		Running();

	2: //Inicia pelo eixo vertical
		PLC.FB_Homing[3].bExecute := TRUE;

		IF PLC.Axis[3].HomeDone THEN
			Homing.State := 3;
		END_IF

	3: //Inicia os outros eixos
		PLC.FB_Homing[1].bExecute := TRUE;
		PLC.FB_Homing[2].bExecute := TRUE;
		PLC.FB_Homing[4].bExecute := TRUE;

		IF PLC.Axis[1].HomeDone AND PLC.Axis[2].HomeDone AND PLC.Axis[4].HomeDone THEN
			Homing.State := 1000;
		END_IF

	999: //Aborta rotina
		Abort();

	1000: //Rotina finalizada
		Done();
END_CASE

(*Habilita eixos*)
Enable(Execute := PLC.Safety_Enabled);

(*Reseta eixos*)
Reset(Execute := bReset);

(*Informa erro nos eixos*)
Erro(Execute := TRUE);

(*Habilita eixos*)
FB_Power[1](Axis := Axis1, Enable := TRUE, bRegulatorOn := Execute, bDriveStart := Execute);
FB_Power[2](Axis := Axis2, Enable := TRUE, bRegulatorOn := Execute, bDriveStart := Execute);
FB_Power[3](Axis := Axis3, Enable := TRUE, bRegulatorOn := Execute, bDriveStart := Execute);
FB_Power[4](Axis := Axis4, Enable := TRUE, bRegulatorOn := Execute, bDriveStart := Execute);

(*Reseta eixos*)
FB_Reset[1](Axis := Axis1, Execute := Execute AND PLC.Axis[1].Error);
FB_Reset[2](Axis := Axis2, Execute := Execute AND PLC.Axis[2].Error);
FB_Reset[3](Axis := Axis3, Execute := Execute AND PLC.Axis[3].Error);
FB_Reset[4](Axis := Axis4, Execute := Execute AND PLC.Axis[4].Error);

(*Informa erro nos eixos*)
FB_Error[1](Axis := Axis1, Enable := Execute, AxisError => PLC.Axis[1].Error, AxisErrorID => PLC.Axis[1].ErrorID);
FB_Error[2](Axis := Axis2, Enable := Execute, AxisError => PLC.Axis[2].Error, AxisErrorID => PLC.Axis[2].ErrorID);
FB_Error[3](Axis := Axis3, Enable := Execute, AxisError => PLC.Axis[3].Error, AxisErrorID => PLC.Axis[3].ErrorID);
FB_Error[4](Axis := Axis4, Enable := Execute, AxisError => PLC.Axis[4].Error, AxisErrorID => PLC.Axis[4].ErrorID);

(*Homing dos eixos*) PLC.FB_Homing[1]( //Eixo 1 Axis := Axis1, fVelocitySlow := PLC.Axis[1].CreepSpeed, fVelocityFast := PLC.Axis[1].HomeSpeed, fAcceleration := PLC.Axis[1].Acceleration, fDeceleration := PLC.Axis[1].Deceleration, nDirection := PLC.Axis[1].HomeDirection, bReferenceSwitch := , nHomingMode := SMC_HOMING_MODE.FAST_BSLOW_STOP_S, bDone => PLC.Axis[1].HomeDone);
PLC.FB_Homing[2]( //Eixo 2 Axis := Axis2, fVelocitySlow := PLC.Axis[2].CreepSpeed, fVelocityFast := PLC.Axis[2].HomeSpeed, fAcceleration := PLC.Axis[2].Acceleration, fDeceleration := PLC.Axis[2].Deceleration, nDirection := PLC.Axis[2].HomeDirection, bReferenceSwitch := , nHomingMode := SMC_HOMING_MODE.FAST_BSLOW_STOP_S, bDone => PLC.Axis[2].HomeDone);
PLC.FB_Homing[3]( //Eixo 3 Axis := Axis3, fVelocitySlow := PLC.Axis[3].CreepSpeed, fVelocityFast := PLC.Axis[3].HomeSpeed, fAcceleration := PLC.Axis[3].Acceleration, fDeceleration := PLC.Axis[3].Deceleration, nDirection := PLC.Axis[3].HomeDirection, bReferenceSwitch := , nHomingMode := SMC_HOMING_MODE.FAST_BSLOW_STOP_S, bDone => PLC.Axis[3].HomeDone);
PLC.FB_Homing[4]( //Eixo 4 Axis := Axis4, fVelocitySlow := PLC.Axis[4].CreepSpeed, fVelocityFast := PLC.Axis[4].HomeSpeed, fAcceleration := PLC.Axis[4].Acceleration, fDeceleration := PLC.Axis[4].Deceleration, nDirection := PLC.Axis[4].HomeDirection, bReferenceSwitch := , nHomingMode := SMC_HOMING_MODE.FAST_BSLOW_STOP_S, bDone => PLC.Axis[4].HomeDone);

(*JOG dos eixos*) FB_Jog[1]( //Eixo 1 Axis := Axis1, JogForward := PLC.Axis[1].JogFwd, JogBackward := PLC.Axis[1].JogRev, Velocity := PLC.Axis[1].ManualSpeed, Acceleration := PLC.Axis[1].Acceleration, Deceleration := PLC.Axis[1].Deceleration);
FB_Jog[2]( //Eixo 2 Axis := Axis2, JogForward := PLC.Axis[2].JogFwd, JogBackward := PLC.Axis[2].JogRev, Velocity := PLC.Axis[2].ManualSpeed, Acceleration := PLC.Axis[2].Acceleration, Deceleration := PLC.Axis[2].Deceleration);
FB_Jog[3]( //Eixo 3 Axis := Axis3, JogForward := PLC.Axis[3].JogFwd, JogBackward := PLC.Axis[3].JogRev, Velocity := PLC.Axis[3].ManualSpeed, Acceleration := PLC.Axis[3].Acceleration, Deceleration := PLC.Axis[3].Deceleration);
FB_Jog[4]( //Eixo 4 Axis := Axis4, JogForward := PLC.Axis[4].JogFwd, JogBackward := PLC.Axis[4].JogRev, Velocity := PLC.Axis[4].ManualSpeed, Acceleration := PLC.Axis[4].Acceleration, Deceleration := PLC.Axis[4].Deceleration);

(*Movimento absoluto para os eixos*) FB_Absolute[1]( //Eixo 1 Axis := Axis1, Execute := PLC.Axis[1].OperationStart, Position := PLC.Axis[1].OperationDistance, Velocity := PLC.Axis[1].OperationSpeed, Acceleration := PLC.Axis[1].Acceleration, Deceleration := PLC.Axis[1].Deceleration, Done => PLC.Axis[1].OperationDone);
FB_Absolute[2]( //Eixo 2 Axis := Axis2, Execute := PLC.Axis[2].OperationStart, Position := PLC.Axis[2].OperationDistance, Velocity := PLC.Axis[2].OperationSpeed, Acceleration := PLC.Axis[2].Acceleration, Deceleration := PLC.Axis[2].Deceleration, Done => PLC.Axis[2].OperationDone);
FB_Absolute[3]( //Eixo 3 Axis := Axis3, Execute := PLC.Axis[3].OperationStart, Position := PLC.Axis[3].OperationDistance, Velocity := PLC.Axis[3].OperationSpeed, Acceleration := PLC.Axis[3].Acceleration, Deceleration := PLC.Axis[3].Deceleration, Done => PLC.Axis[3].OperationDone);
FB_Absolute[4]( //Eixo 4 Axis := Axis4, Execute := PLC.Axis[4].OperationStart, Position := PLC.Axis[4].OperationDistance, Velocity := PLC.Axis[4].OperationSpeed, Acceleration := PLC.Axis[4].Acceleration, Deceleration := PLC.Axis[4].Deceleration, Done => PLC.Axis[4].OperationDone);

(*Stop dos eixos*) FB_Stop[1]( //Eixo 1 Axis := Axis1, Execute := PLC.Axis[1].Stop, Deceleration := PLC.Axis[1].Deceleration);
FB_Stop[2]( //Eixo 2 Axis := Axis2, Execute := PLC.Axis[2].Stop, Deceleration := PLC.Axis[2].Deceleration);
FB_Stop[3]( //Eixo 3 Axis := Axis3, Execute := PLC.Axis[3].Stop, Deceleration := PLC.Axis[3].Deceleration);
FB_Stop[4]( //Eixo 4 Axis := Axis4, Execute := PLC.Axis[4].Stop, Deceleration := PLC.Axis[4].Deceleration);

(*Posição dos eixos*) FB_Position[1]( //Eixo 1 Axis := Axis1, Enable := TRUE, Position => PLC.Axis[1].Position);
FB_Position[2]( //Eixo 2 Axis := Axis2, Enable := TRUE, Position => PLC.Axis[2].Position);
FB_Position[3]( //Eixo 3 Axis := Axis3, Enable := TRUE, Position => PLC.Axis[3].Position);
FB_Position[4]( //Eixo 4 Axis := Axis4, Enable := TRUE, Position => PLC.Axis[4].Position);

(*Homing dos eixos*)
Homing();

(*JOG dos eixos*)
Jogging();

(*Movimento absoluto para os eixos*)
Absolute();

(*Stop dos eixos*)
Stop();

(*Posição dos eixos*)
Position();

(*Eixo 1*)
PLC.Axis[1].Acceleration 	:= IHM.Axis[1].Acceleration;
PLC.Axis[1].CreepSpeed		:= IHM.Axis[1].CreepSpeed;
PLC.Axis[1].Deceleration 	:= IHM.Axis[1].Deceleration;
PLC.Axis[1].HomeDirection 	:= IHM.Axis[1].HomeDirection;
PLC.Axis[1].HomeSpeed 		:= IHM.Axis[1].HomeSpeed;
PLC.Axis[1].JogFwd 			:= IHM.Axis[1].JogFwd;
PLC.Axis[1].JogRev 			:= IHM.Axis[1].JogRev;
PLC.Axis[1].ManualSpeed 	:= IHM.Axis[1].ManualSpeed;
PLC.Axis[1].OperationSpeed 	:= IHM.Axis[1].OperationSpeed;
PLC.Axis[1].Stop 			:= IHM.btStop;
IHM.Axis[1].Position 		:= PLC.Axis[1].Position;

(*Eixo 2*)
PLC.Axis[2].Acceleration 	:= IHM.Axis[2].Acceleration;
PLC.Axis[2].CreepSpeed		:= IHM.Axis[2].CreepSpeed;
PLC.Axis[2].Deceleration 	:= IHM.Axis[2].Deceleration;
PLC.Axis[2].HomeDirection 	:= IHM.Axis[2].HomeDirection;
PLC.Axis[2].HomeSpeed 		:= IHM.Axis[2].HomeSpeed;
PLC.Axis[2].JogFwd 			:= IHM.Axis[2].JogFwd;
PLC.Axis[2].JogRev 			:= IHM.Axis[2].JogRev;
PLC.Axis[2].ManualSpeed 	:= IHM.Axis[2].ManualSpeed;
PLC.Axis[2].OperationSpeed 	:= IHM.Axis[2].OperationSpeed;
PLC.Axis[2].Stop 			:= IHM.btStop;
IHM.Axis[2].Position 		:= PLC.Axis[2].Position;

(*Eixo 3*)
PLC.Axis[3].Acceleration 	:= IHM.Axis[3].Acceleration;
PLC.Axis[3].CreepSpeed		:= IHM.Axis[3].CreepSpeed;
PLC.Axis[3].Deceleration 	:= IHM.Axis[3].Deceleration;
PLC.Axis[3].HomeDirection 	:= IHM.Axis[3].HomeDirection;
PLC.Axis[3].HomeSpeed 		:= IHM.Axis[3].HomeSpeed;
PLC.Axis[3].JogFwd 			:= IHM.Axis[3].JogFwd;
PLC.Axis[3].JogRev 			:= IHM.Axis[3].JogRev;
PLC.Axis[3].ManualSpeed 	:= IHM.Axis[3].ManualSpeed;
PLC.Axis[3].OperationSpeed 	:= IHM.Axis[3].OperationSpeed;
PLC.Axis[3].Stop 			:= IHM.btStop;
IHM.Axis[3].Position 		:= PLC.Axis[3].Position;

(*Eixo 4*)
PLC.Axis[4].Acceleration 	:= IHM.Axis[4].Acceleration;
PLC.Axis[4].CreepSpeed		:= IHM.Axis[4].CreepSpeed;
PLC.Axis[4].Deceleration 	:= IHM.Axis[4].Deceleration;
PLC.Axis[4].HomeDirection 	:= IHM.Axis[4].HomeDirection;
PLC.Axis[4].HomeSpeed 		:= IHM.Axis[4].HomeSpeed;
PLC.Axis[4].JogFwd 			:= IHM.Axis[4].JogFwd;
PLC.Axis[4].JogRev 			:= IHM.Axis[4].JogRev;
PLC.Axis[4].ManualSpeed 	:= IHM.Axis[4].ManualSpeed;
PLC.Axis[4].OperationSpeed 	:= IHM.Axis[4].OperationSpeed;
PLC.Axis[4].Stop 			:= IHM.btStop;
IHM.Axis[4].Position 		:= PLC.Axis[4].Position;

(*Condição para habilitar modo manual*)
IF PLC.Machine = States.Manual THEN
	(*Acionamentos manuais*)
	//Eixo X
	PLC.Axis[1].JogFwd := IHM.Axis[1].JogFwd OR PLC.IO.JogPosX;
	PLC.Axis[1].JogRev := IHM.Axis[1].JogRev OR PLC.IO.JogNegX;
	//Eixo Y
	PLC.Axis[2].JogFwd := IHM.Axis[2].JogFwd OR PLC.IO.JogPosY;
	PLC.Axis[2].JogRev := IHM.Axis[2].JogRev OR PLC.IO.JogNegY;
	//Eixo Z
	PLC.Axis[3].JogFwd := IHM.Axis[3].JogFwd OR PLC.IO.JogPosZ;
	PLC.Axis[3].JogRev := IHM.Axis[3].JogRev OR PLC.IO.JogNegZ;
	//Eixo W
	PLC.Axis[4].JogFwd := IHM.Axis[4].JogFwd OR PLC.IO.JogPosW;
	PLC.Axis[4].JogRev := IHM.Axis[4].JogRev OR PLC.IO.JogNegW;

	(*Definir novo ponto zero*)
	SetPoint(Execute := IHM.btSetPoint);

	(*Retorna para ponto zero*)
	GoToZero(Execute := IHM.btGoToZero);

	(*Girar a serra*)
	RotateSaw(Execute := IHM.btRotateSaw);

	(*Sobe Mesa*)
	TableUp(Execute := IHM.btTableUp);

	(*Desce Mesa*)
	TableDown(Execute := IHM.btTableDown);		
END_IF

(*Condição para iniciar homing*)
IF PLC.Machine = States.Manual THEN
	IF IHM.btStartHome THEN
		Home.Start := TRUE;
		PLC.Machine := States.Homing;
		Home.State := 1;
	END_IF
	(*Condição para parar homing*)
	ELSIF PLC.Machine = States.Homing THEN
		IF IHM.btStop OR PLC.IO.Stop THEN
			PLC.Machine := States.Manual;
			Home.State := 999;
		END_IF
END_IF

(*Rotina de Homing*)
CASE Home.State OF
	1: //Estado rodando
		Homing_Running();

	2: //Inicia pelo eixo vertical
		PLC.FB_Homing[3].bExecute := TRUE;

		IF PLC.Axis[3].HomeDone THEN
			Home.State := 3;
		END_IF

	3: //Inicia os outros eixos
		PLC.FB_Homing[1].bExecute := TRUE;
		PLC.FB_Homing[2].bExecute := TRUE;
		PLC.FB_Homing[4].bExecute := TRUE;

		IF PLC.Axis[1].HomeDone AND PLC.Axis[2].HomeDone AND PLC.Axis[4].HomeDone THEN
			Home.State := 1000;
		END_IF

	999: //Aborta rotina
		Homing_Abort();

	1000: //Rotina finalizada
		Homing_Done();
END_CASE

(*Estado do homing abortando*)
Home.Running := FALSE;
Home.Abort := TRUE;
Home.State := 0;
PLC.FB_Homing[1].bExecute := FALSE;
PLC.FB_Homing[2].bExecute := FALSE;
PLC.FB_Homing[3].bExecute := FALSE;
PLC.FB_Homing[4].bExecute := FALSE;
IHM.btStartHome := FALSE;

(*Estado do homing Finalizado*)
Home.Running := FALSE;
Home.Done := TRUE;
Home.State := 0;
PLC.FB_Homing[1].bExecute := FALSE;
PLC.FB_Homing[2].bExecute := FALSE;
PLC.FB_Homing[3].bExecute := FALSE;
PLC.FB_Homing[4].bExecute := FALSE;
IHM.btStartHome := FALSE;
PLC.Machine := States.Manual;

(*Estado do homing rodando*)
Home.Running := TRUE;
Home.Start := FALSE;
Home.Done := FALSE;
Home.Abort := FALSE;
Home.State := Home.State + 1;

(*Eixo 1*)
PLC.Axis[1].Acceleration 	:= IHM.Axis[1].Acceleration;
PLC.Axis[1].CreepSpeed		:= IHM.Axis[1].CreepSpeed;
PLC.Axis[1].Deceleration 	:= IHM.Axis[1].Deceleration;
PLC.Axis[1].HomeDirection 	:= IHM.Axis[1].HomeDirection;
PLC.Axis[1].HomeSpeed 		:= IHM.Axis[1].HomeSpeed;
PLC.Axis[1].JogFwd 			:= IHM.Axis[1].JogFwd;
PLC.Axis[1].JogRev 			:= IHM.Axis[1].JogRev;
PLC.Axis[1].ManualSpeed 	:= IHM.Axis[1].ManualSpeed;
PLC.Axis[1].OperationSpeed 	:= IHM.Axis[1].OperationSpeed;
PLC.Axis[1].Stop 			:= IHM.btStop;
IHM.Axis[1].Position 		:= PLC.Axis[1].Position;

(*Eixo 2*)
PLC.Axis[2].Acceleration 	:= IHM.Axis[2].Acceleration;
PLC.Axis[2].CreepSpeed		:= IHM.Axis[2].CreepSpeed;
PLC.Axis[2].Deceleration 	:= IHM.Axis[2].Deceleration;
PLC.Axis[2].HomeDirection 	:= IHM.Axis[2].HomeDirection;
PLC.Axis[2].HomeSpeed 		:= IHM.Axis[2].HomeSpeed;
PLC.Axis[2].JogFwd 			:= IHM.Axis[2].JogFwd;
PLC.Axis[2].JogRev 			:= IHM.Axis[2].JogRev;
PLC.Axis[2].ManualSpeed 	:= IHM.Axis[2].ManualSpeed;
PLC.Axis[2].OperationSpeed 	:= IHM.Axis[2].OperationSpeed;
PLC.Axis[2].Stop 			:= IHM.btStop;
IHM.Axis[2].Position 		:= PLC.Axis[2].Position;

(*Eixo 3*)
PLC.Axis[3].Acceleration 	:= IHM.Axis[3].Acceleration;
PLC.Axis[3].CreepSpeed		:= IHM.Axis[3].CreepSpeed;
PLC.Axis[3].Deceleration 	:= IHM.Axis[3].Deceleration;
PLC.Axis[3].HomeDirection 	:= IHM.Axis[3].HomeDirection;
PLC.Axis[3].HomeSpeed 		:= IHM.Axis[3].HomeSpeed;
PLC.Axis[3].JogFwd 			:= IHM.Axis[3].JogFwd;
PLC.Axis[3].JogRev 			:= IHM.Axis[3].JogRev;
PLC.Axis[3].ManualSpeed 	:= IHM.Axis[3].ManualSpeed;
PLC.Axis[3].OperationSpeed 	:= IHM.Axis[3].OperationSpeed;
PLC.Axis[3].Stop 			:= IHM.btStop;
IHM.Axis[3].Position 		:= PLC.Axis[3].Position;

(*Eixo 4*)
PLC.Axis[4].Acceleration 	:= IHM.Axis[4].Acceleration;
PLC.Axis[4].CreepSpeed		:= IHM.Axis[4].CreepSpeed;
PLC.Axis[4].Deceleration 	:= IHM.Axis[4].Deceleration;
PLC.Axis[4].HomeDirection 	:= IHM.Axis[4].HomeDirection;
PLC.Axis[4].HomeSpeed 		:= IHM.Axis[4].HomeSpeed;
PLC.Axis[4].JogFwd 			:= IHM.Axis[4].JogFwd;
PLC.Axis[4].JogRev 			:= IHM.Axis[4].JogRev;
PLC.Axis[4].ManualSpeed 	:= IHM.Axis[4].ManualSpeed;
PLC.Axis[4].OperationSpeed 	:= IHM.Axis[4].OperationSpeed;
PLC.Axis[4].Stop 			:= IHM.btStop;
IHM.Axis[4].Position 		:= PLC.Axis[4].Position;

(*Estado automatico abortando*)
//Peça Retangular
IF CreationPiece_Rectangles.Done THEN
	Auto.Running := FALSE;
	Auto.Abort := TRUE;
	Auto.Done := FALSE;
	Auto.State := 0;
	IHM.btStart := FALSE;
	PLC.CutPiece := 0;
	PLC.CuttingTable90_Step := 0;
	AutomaticRectangle_TotalHeightDisplacement := 0;
	AutomaticRectangle_TotalWidthDisplacement := 0;
	AutomaticRectangle_GeralCutOk := FALSE;
	PLC.CuttingPause := FALSE;
	PLC.IO.SawSpin := FALSE;
	IHM.PauseMessage := FALSE;
	AutomaticRectangle_SecondCutLastPiece := FALSE;
	PLC.Axis[1].OperationAbsolute := FALSE;
	PLC.Axis[2].OperationAbsolute := FALSE;
	PLC.Axis[3].OperationAbsolute := FALSE;
	PLC.Machine := States.Manual;
END_IF

//Peça ortogonal
IF CreationPiece_Orthogonal.Done THEN
	Auto.Running := FALSE;
	Auto.Abort := TRUE;
	Auto.Done := FALSE;
	Auto.State := 0;
	IHM.btStart := FALSE;
	PLC.CutLine := 0;
	PLC.GridTable_Step := 0;
	PLC.IO.SawSpin := FALSE;
	PLC.Axis[1].OperationAbsolute := FALSE;
	PLC.Axis[2].OperationAbsolute := FALSE;
	PLC.Axis[3].OperationAbsolute := FALSE;
	PLC.Machine := States.Manual;
END_IF

//Peça corner (L)
IF CreationPiece_Corner.Done THEN
	Auto.Running := FALSE;
	Auto.Abort := TRUE;
	Auto.Done := FALSE;
	Auto.State := 0;
	IHM.btStart := FALSE;
	PLC.CutStraight := 0;
	AutomaticCorner_CuttingStep := 0;
	PLC.IO.SawSpin := FALSE;
	AutomaticCorner_HorizontalCutting := FALSE;
	PLC.Axis[1].OperationAbsolute := FALSE;
	PLC.Axis[2].OperationAbsolute := FALSE;
	PLC.Axis[3].OperationAbsolute := FALSE;
	PLC.Machine := States.Manual;
END_IF

(*Inicia criação da peça*)
IF IHM.CreationOrthogonal_Start AND CreationPiece_Orthogonal.State = 0 THEN
	CreationPiece_Orthogonal.Start := TRUE;
	CreationPiece_Orthogonal.State := 1;
	(*Cancelar rotina*)
	ELSIF IHM.CancelPiece AND CreationPiece_Orthogonal.State <> 0 THEN
		CreationPiece_Orthogonal.State := 999;
END_IF

(*Rotina de criação de peças ortogonais*)
CASE CreationPiece_Orthogonal.State OF
	1: //Estado rodando
		Creation_Running();

	2: //Remove pontos das linhas de grade
		SysMemSet(ADR(PLC.OrthogonalPieces),0,SIZEOF(PLC.OrthogonalPieces));
		CreationPiece_Orthogonal.State := 5;

	5: //Zera indexadores
		PLC.Grid := 0;
		PLC.GridFigure := 0;
		PLC.GridDesigner_Step := 0;
		CreationPiece_Orthogonal.State := 10;

	10: //Identifica função selecionada pelo operador 
		IF IHM.CreationOrthogonal_MakeOrthogonal THEN
			CreationPiece_Orthogonal.State := 20;
			ELSIF IHM.FinishPiece THEN
				CreationPiece_Orthogonal.State := 200;
		END_IF

	20: //Verifica se a largura e altura é igual a zero
		IF (IHM.NewWidth * IHM.NewHeight * TO_REAL(IHM.CreationOrthogonal_GridLines) * TO_REAL(ihm.CreationOrthogonal_GridColumns)) = 0 THEN
			IHM.ZeroMessage := TRUE;
			CreationPiece_Orthogonal.State := 23;
			ELSIF (IHM.NewWidth * IHM.NewHeight * TO_REAL(IHM.CreationOrthogonal_GridLines) * TO_REAL(ihm.CreationOrthogonal_GridColumns)) <> 0 THEN
				CreationPiece_Orthogonal.State := 21;
		END_IF

	21: //Verifica se a linha que está sendo criada é a primeira
		IF PLC.Grid = 0 THEN
			CreationPiece_Orthogonal.State := 30;
			ELSIF PLC.Grid <> 0 THEN
				CreationPiece_Orthogonal.State := 22;
		END_IF

	22: //Verifica se a linha que está sendo criada é a primeira
		IF PLC.Grid = 21 THEN
			CreationPiece_Orthogonal.State := 40;
			ELSIF PLC.Grid <> 21 THEN
				CreationPiece_Orthogonal.State := 50;
		END_IF

	23: //Reseta bit de mensagem
		IF NOT IHM.ZeroMessage THEN
			IHM.CreationOrthogonal_MakeOrthogonal := FALSE;
			CreationPiece_Orthogonal.State := 10;
		END_IF

	30: //Atualiza zero peça X e Y da primeira linha
		PLC.OrthogonalPieces[PLC.Grid].ZeroPieceX := IHM.PrZeroPieceMachineX;
		PLC.OrthogonalPieces[PLC.Grid].ZeroPieceY := IHM.PrZeroPieceMachineY;
		CreationPiece_Orthogonal.State := 31;

	31: //Atualiza comprimento da linha a ser criada
		PLC.OrthogonalPieces[PLC.Grid].Lenght := (IHM.SawThickness + IHM.NewWidth) * TO_REAL(ihm.CreationOrthogonal_GridColumns);
		CreationPiece_Orthogonal.State := 32;

	32: //Insere valores de ultimo vértica de X
		PLC.OrthogonalPieces[PLC.Grid].LastVertexAbsX := PLC.OrthogonalPieces[PLC.Grid].ZeroPieceX + PLC.OrthogonalPieces[PLC.Grid].Lenght;
		CreationPiece_OrthogonalHeightAxis := TRUE;
		CreationPiece_Orthogonal.State := 80;

	40: //Atualiza zero peça X e Y da primeira linha
		PLC.OrthogonalPieces[PLC.Grid].ZeroPieceX := IHM.PrZeroPieceMachineX;
		PLC.OrthogonalPieces[PLC.Grid].ZeroPieceY := IHM.PrZeroPieceMachineY;
		CreationPiece_Orthogonal.State := 41;

	41: //Atualiza comprimento da linha a ser criada
		PLC.OrthogonalPieces[PLC.Grid].Lenght := (IHM.SawThickness + IHM.NewWidth) * TO_REAL(ihm.CreationOrthogonal_GridColumns);
		CreationPiece_Orthogonal.State := 42;

	42: //Insere valores de ultimo vértica de Y
		PLC.OrthogonalPieces[PLC.Grid].LastVertexAbsY := PLC.OrthogonalPieces[PLC.Grid].ZeroPieceY + PLC.OrthogonalPieces[PLC.Grid].Lenght;
		CreationPiece_OrthogonalWidthAxis := TRUE;
		CreationPiece_Orthogonal.State := 80;

	50: //Verifica se a linha que está sendo criada faz parte das horizontais ou verticais
		IF PLC.Grid > 20 THEN
			CreationPiece_OrthogonalWidthAxis := TRUE;
			CreationPiece_Orthogonal.State := 70;
			ELSIF PLC.Grid < 20 THEN
				CreationPiece_OrthogonalHeightAxis := TRUE;
				CreationPiece_Orthogonal.State := 60;
		END_IF

	60: //Atualiza zero peça X e Y da próxima linha a ser criada
		PLC.OrthogonalPieces[PLC.Grid].ZeroPieceX := PLC.OrthogonalPieces[PLC.Grid - 1].ZeroPieceX;
		PLC.OrthogonalPieces[PLC.Grid].ZeroPieceY := (PLC.OrthogonalPieces[PLC.Grid - 1].ZeroPieceY + IHM.NewHeight + IHM.SawThickness);
		CreationPiece_Orthogonal.State := 61;

	61: //Insere valores de último vértica de X
		PLC.OrthogonalPieces[PLC.Grid].Lenght := PLC.OrthogonalPieces[0].Lenght;
		CreationPiece_Orthogonal.State := 62;

	62: //Atualiza comprimento da linha a ser criada
		PLC.OrthogonalPieces[PLC.Grid].LastVertexAbsX := PLC.OrthogonalPieces[PLC.Grid].ZeroPieceX + PLC.OrthogonalPieces[PLC.Grid].Lenght;
		CreationPiece_Orthogonal.State := 80;

	70: //Atualiza zero peça X e Y da próxima linha a ser criada
		PLC.OrthogonalPieces[PLC.Grid].ZeroPieceX := (PLC.OrthogonalPieces[PLC.Grid - 1].ZeroPieceX + IHM.NewWidth + IHM.SawThickness);
		PLC.OrthogonalPieces[PLC.Grid].ZeroPieceY := PLC.OrthogonalPieces[PLC.Grid - 1].ZeroPieceY;
		CreationPiece_Orthogonal.State := 71;

	71: //Insere valores de ultimo vertica de Y
		PLC.OrthogonalPieces[PLC.Grid].Lenght := PLC.OrthogonalPieces[21].Lenght;
		CreationPiece_Orthogonal.State := 72;

	72: //Atualiza comprimento da liha a ser criada
		PLC.OrthogonalPieces[PLC.Grid].LastVertexAbsY := PLC.OrthogonalPieces[PLC.Grid].ZeroPieceY + PLC.OrthogonalPieces[PLC.Grid].Lenght;
		CreationPiece_Orthogonal.State := 80;

	80: //Cria imagem da linha (A FAZER)
		CreationPiece_Orthogonal.State := 81;

	81: //Ao finalizar a criação da linha, soma 1 no indexador de linha
		PLC.GridDesigner_Step := PLC.GridDesigner_Step + 1;
		CreationPiece_Orthogonal.State := 90;

	90: //Passo
		IF CreationPiece_OrthogonalHeightAxis THEN
			CreationPiece_Orthogonal.State := 110;
			ELSIF CreationPiece_OrthogonalWidthAxis THEN
				CreationPiece_Orthogonal.State := 100;
		END_IF

	100: //Verifica se a imagem que foi criada é igual a quantidade de colunas definida
		IF PLC.Grid = (IHM.CreationOrthogonal_GridColumns + 21) THEN
			CreationPiece_Orthogonal.State := 160;
			ELSIF PLC.Grid <> (IHM.CreationOrthogonal_GridColumns + 21) THEN
				CreationPiece_Orthogonal.State := 120;
		END_IF

	110: //Verifica se a imagem que foi criada é igual a quantidade de linhas definida
		IF PLC.Grid = IHM.CreationOrthogonal_GridLines THEN
			CreationPiece_Orthogonal.State := 130;
			ELSIF PLC.Grid <> IHM.CreationOrthogonal_GridLines THEN
				CreationPiece_Orthogonal.State := 120;
		END_IF

	120: //Ao finalizar a criação da linha, soma 1 no indexador de linha
		PLC.Grid := PLC.Grid + 1;
		CreationPiece_Orthogonal.State := 140;

	130: //Ao finalizar a criação da linha, soma 1 no indexador de linha
		PLC.Grid := 21;
		CreationPiece_Orthogonal.State := 140;

	140: //A nova imagem a ser gerada é sempre realicionada com a linha atual, indexador de imagem recebe numero da linha atual
		PLC.GridFigure := PLC.Grid;
		CreationPiece_Orthogonal.State := 150;

	150: //Reseta bits de criação de linha
		CreationPiece_OrthogonalHeightAxis := FALSE;
		CreationPiece_OrthogonalWidthAxis := FALSE;
		CreationPiece_Orthogonal.State := 20;

	160: // Cria imagem da area de corte
		IHM.CreationOrthogonal_MakeOrthogonal := FALSE;
		CreationPiece_Orthogonal.State := 10;

	200: //Verifica se alguma peça foi criada, caso o banco de dados não possua dados a rotina será encerrada
		IF (PLC.OrthogonalPieces[0].ZeroPieceX + PLC.OrthogonalPieces[0].ZeroPieceY + PLC.OrthogonalPieces[0].LastVertexAbsX + PLC.OrthogonalPieces[0].LastVertexAbsY + PLC.OrthogonalPieces[0].Lenght) = 0 THEN
			CreationPiece_Orthogonal.State := 1000;
			ELSIF (PLC.OrthogonalPieces[0].ZeroPieceX + PLC.OrthogonalPieces[0].ZeroPieceY + PLC.OrthogonalPieces[0].LastVertexAbsX + PLC.OrthogonalPieces[0].LastVertexAbsY + PLC.OrthogonalPieces[0].Lenght) > 0 THEN
				CreationPiece_Orthogonal.State := 210;
		END_IF

	210: //Passo
		PLC.GridDesigner_LastLine := IHM.CreationOrthogonal_GridLines;
		CreationPiece_Orthogonal.State := 1000;

	999: //Abortar rotina;
		Creation_Abort();

	1000: //Finaliza rotina
		Creation_Done();
END_CASE

(*Estado de criação rodando*)
//Peça retangular
IF IHM.CreationRectangle_Start THEN
	CreationPiece_Rectangles.Running := TRUE;
	CreationPiece_Rectangles.Start := FALSE;
	CreationPiece_Rectangles.Done := FALSE;
	CreationPiece_Orthogonal.Done := FALSE;
	CreationPiece_Corner.Done := FALSE;
	CreationPiece_Forms.Done := FALSE;
	CreationPiece_Rectangles.Abort := FALSE;
	CreationPiece_Rectangles.State := CreationPiece_Rectangles.State + 1;
END_IF

//Peça ortogonal
IF IHM.CreationOrthogonal_Start THEN
	CreationPiece_Orthogonal.Running := TRUE;
	CreationPiece_Orthogonal.Start := FALSE;
	CreationPiece_Rectangles.Done := FALSE;
	CreationPiece_Orthogonal.Done := FALSE;
	CreationPiece_Corner.Done := FALSE;
	CreationPiece_Forms.Done := FALSE;
	CreationPiece_Orthogonal.Abort := FALSE;
	CreationPiece_Orthogonal.State := CreationPiece_Orthogonal.State + 1;
END_IF

//Peça em L
IF IHM.CreationCorner_Start THEN
	CreationPiece_Corner.Running := TRUE;
	CreationPiece_Corner.Start := FALSE;
	CreationPiece_Rectangles.Done := FALSE;
	CreationPiece_Orthogonal.Done := FALSE;
	CreationPiece_Corner.Done := FALSE;
	CreationPiece_Forms.Done := FALSE;
	CreationPiece_Corner.Abort := FALSE;
	CreationPiece_Corner.State := CreationPiece_Corner.State + 1;
END_IF

//Peça em formas
IF IHM.CreationForms_Start THEN
	CreationPiece_Forms.Running := TRUE;
	CreationPiece_Forms.Start := FALSE;
	CreationPiece_Rectangles.Done := FALSE;
	CreationPiece_Orthogonal.Done := FALSE;
	CreationPiece_Corner.Done := FALSE;
	CreationPiece_Forms.Done := FALSE;
	CreationPiece_Forms.Abort := FALSE;
	CreationPiece_Forms.State := CreationPiece_Forms.State + 1;
END_IF

(*Estado de automático rodando*)
Auto.Running := TRUE;
Auto.Start := FALSE;
Auto.Done := FALSE;
Auto.Abort := FALSE;
Auto.State := Auto.State + 1;

(*Estado automtico Finalizado*)
//Peça Retangular
IF CreationPiece_Rectangles.Done THEN
	Auto.Running := FALSE;
	Auto.Abort := FALSE;
	Auto.Done := TRUE;
	Auto.State := 0;
	PLC.Machine := States.Manual;
	IHM.btStart := FALSE;
	PLC.CutPiece := 0;
	PLC.CuttingTable90_Step := 0;
	AutomaticRectangle_TotalHeightDisplacement := 0;
	AutomaticRectangle_TotalWidthDisplacement := 0;
	AutomaticRectangle_GeralCutOk := FALSE;
	PLC.CuttingPause := FALSE;
	PLC.IO.SawSpin := FALSE;
	IHM.PauseMessage := FALSE;
	AutomaticRectangle_SecondCutLastPiece := FALSE;
	PLC.Axis[1].OperationAbsolute := FALSE;
	PLC.Axis[2].OperationAbsolute := FALSE;
	PLC.Axis[3].OperationAbsolute := FALSE;
END_IF

//Peça ortogonal
IF CreationPiece_Orthogonal.Done THEN
	Auto.Running := FALSE;
	Auto.Abort := FALSE;
	Auto.Done := TRUE;
	Auto.State := 0;
	IHM.btStart := FALSE;
	PLC.CutLine := 0;
	PLC.GridTable_Step := 0;
	PLC.IO.SawSpin := FALSE;
	PLC.Axis[1].OperationAbsolute := FALSE;
	PLC.Axis[2].OperationAbsolute := FALSE;
	PLC.Axis[3].OperationAbsolute := FALSE;
END_IF

//Peça corner (L)
IF CreationPiece_Corner.Done THEN
	Auto.Running := FALSE;
	Auto.Abort := FALSE;
	Auto.Done := TRUE;
	Auto.State := 0;
	IHM.btStart := FALSE;
	PLC.CutStraight := 0;
	AutomaticCorner_CuttingStep := 0;
	PLC.IO.SawSpin := FALSE;
	AutomaticCorner_HorizontalCutting := FALSE;
	PLC.Axis[1].OperationAbsolute := FALSE;
	PLC.Axis[2].OperationAbsolute := FALSE;
	PLC.Axis[3].OperationAbsolute := FALSE;
END_IF

(*Inicia criação da peça*)
IF IHM.CreationRectangle_Start AND CreationPiece_Rectangles.State = 0 THEN
	CreationPiece_Rectangles.Start := TRUE;
	CreationPiece_Rectangles.State := 1;
	(*Cancelar rotina*)
	ELSIF IHM.CancelPiece AND CreationPiece_Rectangles.State <> 0 THEN
		CreationPiece_Rectangles.State := 999;
END_IF

(*Rotina de criação de peças retangulares*)
CASE CreationPiece_Rectangles.State OF
	1: //Estado rodando
		Creation_Running();

	2: //Remove os pontos da ultima peça criada
		SysMemSet(ADR(PLC.RectangularPieces),0,SIZEOF(PLC.RectangularPieces));
		CreationPiece_Rectangles.State := 3;

	3: // Zera indexadores
		PLC.Piece := 0;
		PLC.PieceFigure := 0;
		CreationPiece_Rectangles.State := 4;

	4: //Zera maiores valores de altura e largura
		PLC.CreationRectangles_GreatestHeight := 0;
		PLC.CreationRectangles_GreatestWidth := 0;
		CreationPiece_Rectangles.State := 10;

	10: //Identifica função selecionada pelo operador 
		IF IHM.CreationRectangle_MakeNewPieceSide OR IHM.CreationRectangle_MakeNewPieceDown THEN
			CreationPiece_Rectangles.State := 20;
			ELSIF IHM.DeleteLastPiece AND PLC.Piece <> 0 THEN
				CreationPiece_Rectangles.State := 200;
				ELSIF IHM.FinishPiece THEN
					CreationPiece_Rectangles.State := 300;
		END_IF

	20: //Verifica se a largura e altura são iguais a zero
		IF (IHM.NewWidth * IHM.NewHeight) = 0 THEN
			IHM.ZeroMessage := TRUE;
			CreationPiece_Rectangles.State := 22;
			ELSIF (IHM.NewWidth * IHM.NewHeight) <> 0 THEN
				CreationPiece_Rectangles.State := 21;
		END_IF

	21: //Verifica se é a primeira peça
		IF PLC.Piece = 0 THEN
			CreationPiece_Rectangles.State := 30;
			ELSIF PLC.Piece <> 0 THEN
				CreationPiece_Rectangles.State := 40;
		END_IF

	22: //Reseta bit da mensagem
		IF NOT IHM.ZeroMessage THEN
			CreationPiece_Rectangles.State := 120;
		END_IF

	30: //Atualiza Zero peça X e Y da primeira peça criada
		PLC.RectangularPieces[PLC.Piece].ZeroPieceX := IHM.PrZeroPieceMachineX;
		PLC.RectangularPieces[PLC.Piece].ZeroPieceY := IHM.PrZeroPieceMachineY;
		CreationPiece_Rectangles.State := 50;

	40: //Atualiza Zero peça X e Y da nova peça criada
		IF IHM.CreationRectangle_MakeNewPieceSide THEN
			PLC.RectangularPieces[PLC.Piece].ZeroPieceX := (PLC.RectangularPieces[PLC.Piece - 1].ZeroPieceX + PLC.RectangularPieces[PLC.Piece - 1].Width + IHM.SawThickness);
			PLC.RectangularPieces[PLC.Piece].ZeroPieceY := PLC.RectangularPieces[PLC.Piece - 1].ZeroPieceY;
			CreationPiece_Rectangles.State := 50;
		END_IF

		IF IHM.CreationRectangle_MakeNewPieceDown THEN
			PLC.RectangularPieces[PLC.Piece].ZeroPieceX := PLC.RectangularPieces[PLC.Piece - 1].ZeroPieceX;
			PLC.RectangularPieces[PLC.Piece].ZeroPieceY := (PLC.RectangularPieces[PLC.Piece - 1].ZeroPieceY + PLC.RectangularPieces[PLC.Piece - 1].Height + IHM.SawThickness);
			CreationPiece_Rectangles.State := 50;
		END_IF

	50: //Insere largura e altura da nova peça
		PLC.RectangularPieces[PLC.Piece].Width := IHM.NewWidth;
		PLC.RectangularPieces[PLC.Piece].Height := IHM.NewHeight;
		CreationPiece_Rectangles.State := 51;

	51: //Insere valores do ultimo vertice de X e Y
		PLC.RectangularPieces[PLC.Piece].LastVertexAbsX := PLC.RectangularPieces[PLC.Piece].ZeroPieceX + PLC.RectangularPieces[PLC.Piece].Width;
		PLC.RectangularPieces[PLC.Piece].LastVertexAbsY := PLC.RectangularPieces[PLC.Piece].ZeroPieceY + PLC.RectangularPieces[PLC.Piece].Height;
		CreationPiece_Rectangles.State := 60;

	60: //Verifica se é a primeira peça criada
		IF PLC.Piece = 0 THEN
			CreationPiece_Rectangles.State := 71;
			ELSIF PLC.Piece <> 0 THEN
				CreationPiece_Rectangles.State := 61;
		END_IF

	61: //Verifica se a peça criada tem a altura igual a peça anterior
		IF NOT IHM.CutMode THEN
			IF PLC.RectangularPieces[PLC.Piece].Height = PLC.RectangularPieces[PLC.Piece - 1].Height THEN
				CreationPiece_Rectangles.State := 70;
				ELSIF PLC.RectangularPieces[PLC.Piece].Height <> PLC.RectangularPieces[PLC.Piece - 1].Height THEN
					CreationPiece_Rectangles.State := 71;
			END_IF
		END_IF
		IF IHM.CutMode THEN
			IF PLC.RectangularPieces[PLC.Piece].Width = PLC.RectangularPieces[PLC.Piece - 1].Width THEN
				CreationPiece_Rectangles.State := 70;
				ELSIF PLC.RectangularPieces[PLC.Piece].Width <> PLC.RectangularPieces[PLC.Piece - 1].Width THEN
					CreationPiece_Rectangles.State := 71;
			END_IF
		END_IF

	70: //Série de tamanhos iguais recebe o valor da série anterior + 1
		PLC.RectangularPieces[PLC.Piece].EqualSerie := (PLC.RectangularPieces[PLC.Piece - 1].EqualSerie + 1);
		CreationPiece_Rectangles.State := 80;

	71: //Série de tamanhos iguais recebe 1
		PLC.RectangularPieces[PLC.Piece].EqualSerie := 1;
		CreationPiece_Rectangles.State := 80;

	80: //Cria imagem da peça
		CreationPiece_Rectangles.State := 90;

	90: //Define maior altura do conjunto de peças
		PLC.CreationRectangles_GreatestHeight := MAX(
			PLC.RectangularPieces[0].Height,
			PLC.RectangularPieces[1].Height,
			PLC.RectangularPieces[2].Height,
			PLC.RectangularPieces[3].Height,
			PLC.RectangularPieces[4].Height,
			PLC.RectangularPieces[5].Height,
			PLC.RectangularPieces[6].Height,
			PLC.RectangularPieces[7].Height,
			PLC.RectangularPieces[8].Height,
			PLC.RectangularPieces[9].Height,
			PLC.RectangularPieces[10].Height,
			PLC.RectangularPieces[11].Height,
			PLC.RectangularPieces[12].Height,
			PLC.RectangularPieces[13].Height,
			PLC.RectangularPieces[14].Height,
			PLC.RectangularPieces[15].Height,
			PLC.RectangularPieces[16].Height,
			PLC.RectangularPieces[17].Height,
			PLC.RectangularPieces[18].Height,
			PLC.RectangularPieces[19].Height);

		CreationPiece_Rectangles.State := 91;

	91: ///Define maior largura do conjunto de peças
		PLC.CreationRectangles_GreatestWidth := MAX(
			PLC.RectangularPieces[0].Width,
			PLC.RectangularPieces[1].Width,
			PLC.RectangularPieces[2].Width,
			PLC.RectangularPieces[3].Width,
			PLC.RectangularPieces[4].Width,
			PLC.RectangularPieces[5].Width,
			PLC.RectangularPieces[6].Width,
			PLC.RectangularPieces[7].Width,
			PLC.RectangularPieces[8].Width,
			PLC.RectangularPieces[9].Width,
			PLC.RectangularPieces[10].Width,
			PLC.RectangularPieces[11].Width,
			PLC.RectangularPieces[12].Width,
			PLC.RectangularPieces[13].Width,
			PLC.RectangularPieces[14].Width,
			PLC.RectangularPieces[15].Width,
			PLC.RectangularPieces[16].Width,
			PLC.RectangularPieces[17].Width,
			PLC.RectangularPieces[18].Width,
			PLC.RectangularPieces[19].Width);

		CreationPiece_Rectangles.State := 100;

	100: //Soma no indexador
		PLC.Piece := PLC.Piece + 1;
		CreationPiece_Rectangles.State := 110;

	110: //Soma na quantidade de figuras
		PLC.PieceFigure := PLC.Piece;
		CreationPiece_Rectangles.State := 120;

	120: //Reseta bits de criação de peça
		IHM.CreationRectangle_MakeNewPieceDown := FALSE;
		IHM.CreationRectangle_MakeNewPieceSide := FALSE;
		CreationPiece_Rectangles.State := 10;

	200: //Remove pontos da ultima peça criada
		PLC.RectangularPieces[PLC.Piece - 1].EqualSerie := 0;
		PLC.RectangularPieces[PLC.Piece - 1].Height := 0;
		PLC.RectangularPieces[PLC.Piece - 1].LastVertexAbsX := 0;
		PLC.RectangularPieces[PLC.Piece - 1].LastVertexAbsY := 0;
		PLC.RectangularPieces[PLC.Piece - 1].Width := 0;
		PLC.RectangularPieces[PLC.Piece - 1].ZeroPieceX := 0;
		PLC.RectangularPieces[PLC.Piece - 1].ZeroPieceY := 0;
		CreationPiece_Rectangles.State := 220;

	220: //Subtrai no indexador
		PLC.Piece := PLC.Piece - 1;
		CreationPiece_Rectangles.State := 230;

	230: //Subtrai na quantidade de figuras
		PLC.PieceFigure := PLC.Piece;
		CreationPiece_Rectangles.State := 240;

	240: //Define maior altura do conjunto de peças
		PLC.CreationRectangles_GreatestHeight := MAX(
			PLC.RectangularPieces[0].Height,
			PLC.RectangularPieces[1].Height,
			PLC.RectangularPieces[2].Height,
			PLC.RectangularPieces[3].Height,
			PLC.RectangularPieces[4].Height,
			PLC.RectangularPieces[5].Height,
			PLC.RectangularPieces[6].Height,
			PLC.RectangularPieces[7].Height,
			PLC.RectangularPieces[8].Height,
			PLC.RectangularPieces[9].Height,
			PLC.RectangularPieces[10].Height,
			PLC.RectangularPieces[11].Height,
			PLC.RectangularPieces[12].Height,
			PLC.RectangularPieces[13].Height,
			PLC.RectangularPieces[14].Height,
			PLC.RectangularPieces[15].Height,
			PLC.RectangularPieces[16].Height,
			PLC.RectangularPieces[17].Height,
			PLC.RectangularPieces[18].Height,
			PLC.RectangularPieces[19].Height);

		CreationPiece_Rectangles.State := 241;

	241: //Define maior largura do conjunto de peças
		PLC.CreationRectangles_GreatestWidth := MAX(
			PLC.RectangularPieces[0].Width,
			PLC.RectangularPieces[1].Width,
			PLC.RectangularPieces[2].Width,
			PLC.RectangularPieces[3].Width,
			PLC.RectangularPieces[4].Width,
			PLC.RectangularPieces[5].Width,
			PLC.RectangularPieces[6].Width,
			PLC.RectangularPieces[7].Width,
			PLC.RectangularPieces[8].Width,
			PLC.RectangularPieces[9].Width,
			PLC.RectangularPieces[10].Width,
			PLC.RectangularPieces[11].Width,
			PLC.RectangularPieces[12].Width,
			PLC.RectangularPieces[13].Width,
			PLC.RectangularPieces[14].Width,
			PLC.RectangularPieces[15].Width,
			PLC.RectangularPieces[16].Width,
			PLC.RectangularPieces[17].Width,
			PLC.RectangularPieces[18].Width,
			PLC.RectangularPieces[19].Width);

		IHM.DeleteLastPiece := FALSE;
		CreationPiece_Rectangles.State := 10;

	300: //Verifica se alguma peça foi criada, caso o banco de dados não possua dados a rotina será encerrada
		IF (PLC.RectangularPieces[0].Height + PLC.RectangularPieces[0].LastVertexAbsX + PLC.RectangularPieces[0].LastVertexAbsY + PLC.RectangularPieces[0].Width + PLC.RectangularPieces[0].ZeroPieceX + PLC.RectangularPieces[0].ZeroPieceY + TO_REAL(PLC.RectangularPieces[0].EqualSerie)) = 0 THEN
			CreationPiece_Rectangles.State := 1000;
			ELSE
				CreationPiece_Rectangles.State := 310;
		END_IF

	310: //Define ultima peça criada
		PLC.LastPiece := (PLC.Piece - 1);
		CreationPiece_Rectangles.State := 1000;

	999: //Abortar rotina
		Creation_Abort();

	1000: //Rotina finalizada
		Creation_Done();
END_CASE

(*Estado para abortar rotina*)

//Peça retangular
IF IHM.CreationRectangle_Start AND IHM.CancelPiece THEN
	CreationPiece_Rectangles.Running := FALSE;
	CreationPiece_Rectangles.Start := FALSE;
	CreationPiece_Rectangles.Done := FALSE;
	CreationPiece_Rectangles.Abort := TRUE;
	CreationPiece_Rectangles.State := 0;
	IHM.CreationRectangle_Start := FALSE;
	IHM.CancelPiece := FALSE;
	IHM.FinishPiece := FALSE;
	IHM.CreationRectangle_MakeNewPieceSide := FALSE;
	IHM.CreationRectangle_MakeNewPieceDown := FALSE;
	IHM.DeleteLastPiece := FALSE;
END_IF

//Peça ortogonal
IF IHM.CreationOrthogonal_Start THEN
	CreationPiece_Orthogonal.Running := FALSE;
	CreationPiece_Orthogonal.Start := FALSE;
	CreationPiece_Orthogonal.Done := FALSE;
	CreationPiece_Orthogonal.Abort := TRUE;
	CreationPiece_Orthogonal.State := 0;
	IHM.CreationOrthogonal_Start := FALSE;
	IHM.CancelPiece := FALSE;
	IHM.FinishPiece := FALSE;
	CreationPiece_OrthogonalHeightAxis := FALSE;
	CreationPiece_OrthogonalWidthAxis := FALSE;
END_IF

//Peça em L
IF IHM.CreationCorner_Start THEN
	CreationPiece_Corner.Running := FALSE;
	CreationPiece_Corner.Start := FALSE;
	CreationPiece_Corner.Done := FALSE;
	CreationPiece_Corner.Abort := TRUE;
	CreationPiece_Corner.State := 0;
	IHM.CreationCorner_Start := FALSE;
	IHM.CancelPiece := FALSE;
	IHM.FinishPiece := FALSE;
	CreationPiece_CornerHalfDone := FALSE;
	IHM.CreationRectangle_MakeNewPieceSide := FALSE;
	IHM.CreationRectangle_MakeNewPieceDown := FALSE;
	IHM.CreationCorner_MakeCorner := FALSE;
END_IF

//Peça em formas
IF IHM.CreationForms_Start THEN
	CreationPiece_Forms.Running := FALSE;
	CreationPiece_Forms.Start := FALSE;
	CreationPiece_Forms.Done := FALSE;
	CreationPiece_Forms.Abort := TRUE;
	CreationPiece_Forms.State := 0;
	IHM.CreationForms_Start := FALSE;
	IHM.CancelPiece := FALSE;
	IHM.FinishPiece := FALSE;
END_IF

(*Estado para finalizar rotina*)

//Peça retangular
IF IHM.CreationRectangle_Start THEN
	CreationPiece_Rectangles.Running := FALSE;
	CreationPiece_Rectangles.Start := FALSE;
	CreationPiece_Rectangles.Done := TRUE;
	CreationPiece_Rectangles.Abort := FALSE;
	CreationPiece_Rectangles.State := 0;
	IHM.CreationRectangle_Start := FALSE;
	IHM.FinishPiece := FALSE;
	IHM.CreationRectangle_MakeNewPieceSide := FALSE;
	IHM.CreationRectangle_MakeNewPieceDown := FALSE;
	IHM.DeleteLastPiece := FALSE;
END_IF

//Peça ortogonal
IF IHM.CreationOrthogonal_Start THEN
	CreationPiece_Orthogonal.Running := FALSE;
	CreationPiece_Orthogonal.Start := FALSE;
	CreationPiece_Orthogonal.Done := TRUE;
	CreationPiece_Orthogonal.Abort := FALSE;
	CreationPiece_Orthogonal.State := 0;
	IHM.CreationOrthogonal_Start := FALSE;
	IHM.FinishPiece := FALSE;
	CreationPiece_OrthogonalHeightAxis := FALSE;
	CreationPiece_OrthogonalWidthAxis := FALSE;
END_IF

//Peça em L
IF IHM.CreationCorner_Start THEN
	CreationPiece_Corner.Running := FALSE;
	CreationPiece_Corner.Start := FALSE;
	CreationPiece_Corner.Done := TRUE;
	CreationPiece_Corner.Abort := FALSE;
	CreationPiece_Corner.State := 0;
	IHM.CreationCorner_Start := FALSE;
	IHM.CancelPiece := FALSE;
	IHM.FinishPiece := FALSE;
	CreationPiece_CornerHalfDone := FALSE;
	IHM.CreationRectangle_MakeNewPieceSide := FALSE;
	IHM.CreationRectangle_MakeNewPieceDown := FALSE;
	IHM.CreationCorner_MakeCorner := FALSE;
END_IF

//Peça em formas
IF IHM.CreationForms_Start THEN
	CreationPiece_Forms.Running := FALSE;
	CreationPiece_Forms.Start := FALSE;
	CreationPiece_Forms.Done := TRUE;
	CreationPiece_Forms.Abort := FALSE;
	CreationPiece_Forms.State := 0;
	IHM.CreationForms_Start := FALSE;
	IHM.CancelPiece := FALSE;
	IHM.FinishPiece := FALSE;
END_IF

(*Inicia criação de peça*)
IF IHM.CreationCorner_Start AND CreationPiece_Corner.State = 0 THEN
	CreationPiece_Corner.Start := TRUE;
	CreationPiece_Corner.State := 1;
	(*Cancelar rotina*)
	ELSIF IHM.CancelPiece AND CreationPiece_Corner.State <> 0 THEN
		CreationPiece_Corner.State := 999;
END_IF

(*Rotina de criação de peças em L*)
CASE CreationPiece_Corner.State OF
	1: //Estado rodando
		Creation_Running();

	2: //Remove pontos das linhas
		SysMemSet(ADR(PLC.CornerPieces),0,SIZEOF(PLC.CornerPieces));
		CreationPiece_Corner.State := 5;

	5: //Zera indexadores
		PLC.CornerArea := 0;
		PLC.CornerAreaFigure := 0;
		PLC.CornerDesigner_LastCornerArea := 0;
		PLC.CornerDesigner_Step := 0;
		CreationPiece_Corner.State := 10;

	10: //Identifica função solicitada
		IF (IHM.CreationCorner_MakeCorner AND NOT IHM.CutMode) OR (IHM.CreationCorner_MakeCorner AND IHM.CutMode) THEN
			IHM.CreationRectangle_MakeNewPieceSide := TRUE;
			IHM.CreationRectangle_MakeNewPieceDown := TRUE;
			PLC.CornerArea := 0;
			PLC.CornerAreaFigure := 0;
			PLC.CornerDesigner_LastCornerArea := 0;
			PLC.CornerDesigner_Step := 0;
			CreationPiece_Corner.State := 20;
			ELSIF IHM.FinishPiece THEN
				CreationPiece_Corner.State := 200;
		END_IF

	20: //Verifica se a largura e altura é igual a zero
		IF (IHM.CreationCorner_X1 * IHM.CreationCorner_X2 * IHM.CreationCorner_Y1 * IHM.CreationCorner_Y2) = 0 THEN
			IHM.ZeroMessage := TRUE;
			CreationPiece_Corner.State := 21;
			ELSIF (IHM.CreationCorner_X1 * IHM.CreationCorner_X2 * IHM.CreationCorner_Y1 * IHM.CreationCorner_Y2) <> 0 THEN
				CreationPiece_Corner.State := 30;
		END_IF

	21: //Reseta bit de mensagem
		IF NOT IHM.ZeroMessage THEN
			CreationPiece_Corner.State := 170;
		END_IF

	30: //Insere largura e altura da nova peça
		IF PLC.CornerArea = 0 THEN
			CreationPiece_Corner.State := 31;
			ELSIF PLC.CornerArea = 3 THEN
				CreationPiece_Corner.State := 32;
				ELSIF PLC.CornerArea = 1 THEN
					CreationPiece_Corner.State := 33;
					ELSIF PLC.CornerArea = 2 THEN
						CreationPiece_Corner.State := 34;
						ELSIF PLC.CornerArea = 4 THEN
							CreationPiece_Corner.State := 110;
		END_IF

	31: //Atualiza zero peça X e Y da primeira peça a ser criada
		PLC.CornerSquares[PLC.CornerArea].ZeroPieceX := IHM.PrZeroPieceMachineX;
		PLC.CornerSquares[PLC.CornerArea].ZeroPieceY := IHM.PrZeroPieceMachineY;
		CreationPiece_Corner.State := 41;

	32: //Atualiza zero peça X e Y da nova peça a ser criada
		PLC.CornerSquares[PLC.CornerArea].ZeroPieceX := PLC.CornerSquares[PLC.CornerArea - 1].LastVertexAbsX + 0;
		PLC.CornerSquares[PLC.CornerArea].ZeroPieceY := PLC.CornerSquares[PLC.CornerArea - 1].ZeroPieceY;
		CreationPiece_Corner.State := 41;

	33: //Atualiza zero peça X e Y da nova peça a ser criada
		IF IHM.CreationCorner_ReverseCorner THEN
			PLC.CornerSquares[PLC.CornerArea].ZeroPieceX := PLC.CornerSquares[PLC.CornerArea - 1].LastVertexAbsX + 0;
			PLC.CornerSquares[PLC.CornerArea].ZeroPieceY := PLC.CornerSquares[PLC.CornerArea -1].ZeroPieceY;
			CreationPiece_Corner.State := 42;
			ELSIF NOT IHM.CreationCorner_ReverseCorner THEN
				PLC.CornerSquares[PLC.CornerArea].ZeroPieceX := PLC.CornerSquares[PLC.CornerArea - 1].LastVertexAbsX + 0;
				PLC.CornerSquares[PLC.CornerArea].ZeroPieceY := PLC.CornerSquares[PLC.CornerArea - 1].LastVertexAbsY + (IHM.CreationCorner_Y2 * -1) + 0;
				CreationPiece_Corner.State := 42;
		END_IF

	34: //Atualiza zero peça X e Y da nova peça a ser criada
		PLC.CornerSquares[PLC.CornerArea].ZeroPieceX := PLC.CornerSquares[0].LastVertexAbsX + IHM.SawThickness + IHM.CreationCorner_CornerDisplacement;
		PLC.CornerSquares[PLC.CornerArea].ZeroPieceY := PLC.CornerSquares[1].ZeroPieceY + (IHM.SawThickness * -1) + (IHM.CreationCorner_Y2 * -1);
		CreationPiece_Corner.State := 42;

	41: //Insere largura e altura da nova peça
		PLC.CornerSquares[PLC.CornerArea].Width := IHM.CreationCorner_X2 + 0;
		PLC.CornerSquares[PLC.CornerArea].Height := IHM.CreationCorner_Y1 + 0;
		CreationPiece_Corner.State := 50;

	42: //Insere altura e largura da nova peça
		PLC.CornerSquares[PLC.CornerArea].Width := IHM.CreationCorner_X1 + (IHM.CreationCorner_X2 * -1);
		PLC.CornerSquares[PLC.CornerArea].Height := IHM.CreationCorner_Y2 + 0;
		CreationPiece_Corner.State := 50;

	50: //Insere valores de ultimo vertice de X e Y
		PLC.CornerSquares[PLC.CornerArea].LastVertexAbsX := PLC.CornerSquares[PLC.CornerArea].ZeroPieceX + PLC.CornerSquares[PLC.CornerArea].Width;
		PLC.CornerSquares[PLC.CornerArea].LastVertexAbsY := PLC.CornerSquares[PLC.CornerArea].ZeroPieceY + PLC.CornerSquares[PLC.CornerArea].Height;
		CreationPiece_Corner.State := 60;

	60: //Cria imagem da peça
		CreationPiece_Corner.State := 61;

	61: //Passo
		PLC.CornerDesigner_Step := PLC.CornerDesigner_Step + 1;
		CreationPiece_Corner.State := 70;

	70: //Ao finalizar a criação da imagem, soma 1 no indexador de peça
		PLC.CornerArea := PLC.CornerArea + 1;
		CreationPiece_Corner.State := 80;

	80: //A nova imagem a ser gerada é sempre relacionada com a peça atual, indexador de imagem recebe numero da peça atual
		PLC.CornerAreaFigure := PLC.CornerArea;
		CreationPiece_Corner.State := 90;

	90: //Reseta bit de criação de peça
		IF NOT CreationPiece_CornerHalfDone THEN
			CreationPiece_Corner.State := 91;
			ELSIF CreationPiece_CornerHalfDone THEN
				CreationPiece_Corner.State := 100;
		END_IF

	91: //Reseta bit de criação
		CreationPiece_CornerHalfDone := TRUE;
		CreationPiece_Corner.State := 30;

	100: //Reseta bit de criação de peça
		IF NOT IHM.CreationCorner_MirrorCorner THEN
			CreationPiece_Corner.State := 110;
			ELSIF IHM.CreationCorner_MirrorCorner THEN
				CreationPiece_CornerHalfDone := FALSE;
				CreationPiece_Corner.State := 30;
		END_IF

	110: //Linha 0
		PLC.CornerPieces[0].ZeroPieceX := PLC.CornerSquares[0].ZeroPieceX;
		PLC.CornerPieces[0].ZeroPieceY := PLC.CornerSquares[0].ZeroPieceY;
		PLC.CornerPieces[0].Height := PLC.CornerSquares[0].Height;
		PLC.CornerPieces[0].LastVertexAbsY := PLC.CornerSquares[0].LastVertexAbsY;
		PLC.CornerPieces[0].EntryEdge := IHM.PrEntryEdgeY;
		PLC.CornerPieces[0].LeadingEdge := IHM.PrLeadingEdgeY;
		CreationPiece_Corner.State := 120;

	120: //Linha 1
		PLC.CornerPieces[1].ZeroPieceX := PLC.CornerSquares[0].LastVertexAbsX + IHM.SawThickness;
		IF NOT IHM.CreationCorner_ReverseCorner THEN
			PLC.CornerPieces[1].ZeroPieceY := PLC.CornerSquares[0].ZeroPieceY;
			PLC.CornerPieces[1].EntryEdge := IHM.PrEntryEdgeY;
			PLC.CornerPieces[1].LeadingEdge := IHM.PrCornerEdgeY;
			ELSIF IHM.CreationCorner_ReverseCorner THEN
				PLC.CornerPieces[1].ZeroPieceY := PLC.CornerSquares[0].ZeroPieceY + IHM.CreationCorner_Y2;
				PLC.CornerPieces[1].EntryEdge := IHM.PrReverseCornerEntryY;
				PLC.CornerPieces[1].LeadingEdge := IHM.PrLeadingEdgeY;
		END_IF
		PLC.CornerPieces[1].Height := IHM.CreationCorner_Y1 - IHM.CreationCorner_Y2;
		PLC.CornerPieces[1].LastVertexAbsY := PLC.CornerSquares[0].ZeroPieceY + (IHM.CreationCorner_Y1 - IHM.CreationCorner_Y2);
		CreationPiece_Corner.State := 130;

	130: //Linha 2
		PLC.CornerPieces[2].ZeroPieceX := PLC.CornerSquares[1].LastVertexAbsX + IHM.SawThickness;
		PLC.CornerPieces[2].ZeroPieceY := PLC.CornerSquares[1].ZeroPieceY;
		IF NOT IHM.CreationCorner_MirrorCorner THEN
			PLC.CornerPieces[2].Height := PLC.CornerSquares[1].Height;
			PLC.CornerPieces[2].EntryEdge := IHM.PrEntryEdgeY;
			ELSIF IHM.CreationCorner_MirrorCorner THEN
				PLC.CornerPieces[2].Height := IHM.CreationCorner_Y1 + (IHM.CreationCorner_Y2 * -1);
				PLC.CornerPieces[2].EntryEdge := IHM.PrCornerEdgeY;		
		END_IF
		PLC.CornerPieces[2].LastVertexAbsY := PLC.CornerSquares[1].LastVertexAbsY;
		PLC.CornerPieces[2].LeadingEdge := IHM.PrLeadingEdgeY;
		CreationPiece_Corner.State := 140;

	140: //Linha 3
		IF NOT IHM.CreationCorner_MirrorCorner THEN
			PLC.CornerPieces[3].ZeroPieceX := PLC.CornerSquares[0].ZeroPieceX;
			PLC.CornerPieces[3].ZeroPieceY := PLC.CornerSquares[0].LastVertexAbsY + IHM.SawThickness;
			IF NOT IHM.CreationCorner_ReverseCorner THEN
				PLC.CornerPieces[3].Width := IHM.CreationCorner_X1;
				PLC.CornerPieces[3].LastVertexAbsX := PLC.CornerSquares[0].ZeroPieceX + IHM.CreationCorner_X1;
				ELSIF IHM.CreationCorner_ReverseCorner THEN
					PLC.CornerPieces[3].Width := PLC.CornerSquares[0].Width;
					PLC.CornerPieces[3].LastVertexAbsX := PLC.CornerSquares[0].ZeroPieceX + PLC.CornerSquares[0].Width;
			END_IF
			PLC.CornerPieces[3].EntryEdge := IHM.PrEntryEdgeX;
			PLC.CornerPieces[3].LeadingEdge := IHM.PrLeadingEdgeX;
			CreationPiece_Corner.State := 150;
			ELSIF IHM.CreationCorner_MirrorCorner THEN
				PLC.CornerPieces[3].ZeroPieceX := PLC.CornerSquares[3].LastVertexAbsX + IHM.SawThickness;
				PLC.CornerPieces[3].ZeroPieceY := PLC.CornerSquares[3].ZeroPieceY;
				PLC.CornerPieces[3].Height := PLC.CornerSquares[3].Height;
				PLC.CornerPieces[3].LastVertexAbsY := PLC.CornerSquares[3].ZeroPieceY + IHM.CreationCorner_X1;
				PLC.CornerPieces[3].EntryEdge := IHM.PrEntryEdgeY;
				PLC.CornerPieces[3].LeadingEdge := IHM.PrLeadingEdgeY;
				CreationPiece_Corner.State := 150;
		END_IF

	150: //Linha 4
		IF NOT IHM.CreationCorner_MirrorCorner THEN
			IF NOT IHM.CreationCorner_ReverseCorner THEN
				PLC.CornerPieces[4].ZeroPieceX := PLC.CornerSquares[1].ZeroPieceX;
				PLC.CornerPieces[4].ZeroPieceY := PLC.CornerSquares[1].ZeroPieceY;
				PLC.CornerPieces[4].LeadingEdge := IHM.PrCornerEdgeX;
				ELSIF IHM.CreationCorner_ReverseCorner THEN
					PLC.CornerPieces[4].ZeroPieceX := PLC.CornerSquares[1].ZeroPieceX;
					PLC.CornerPieces[4].ZeroPieceY := PLC.CornerSquares[1].LastVertexAbsY + IHM.SawThickness;
					PLC.CornerPieces[4].LeadingEdge := IHM.PrReverseCornerEntryX;
			END_IF
			PLC.CornerPieces[4].Width := PLC.CornerSquares[1].Width;
			PLC.CornerPieces[4].LastVertexAbsX := PLC.CornerSquares[1].ZeroPieceX + PLC.CornerSquares[1].Width;
			PLC.CornerPieces[4].EntryEdge := IHM.PrEntryEdgeX;
			PLC.CornerPieces[4].LeadingEdge := IHM.PrCornerEdgeX;
			CreationPiece_Corner.State := 160;
			ELSIF IHM.CreationCorner_MirrorCorner THEN
				PLC.CornerPieces[4].ZeroPieceX := PLC.CornerSquares[3].ZeroPieceX;
				PLC.CornerPieces[4].ZeroPieceY := PLC.CornerSquares[3].LastVertexAbsY + IHM.SawThickness;
				PLC.CornerPieces[4].Width := PLC.CornerSquares[3].Width;
				PLC.CornerPieces[4].LastVertexAbsX := PLC.CornerSquares[3].LastVertexAbsX;
				PLC.CornerPieces[4].EntryEdge := IHM.PrEntryEdgeX;
				PLC.CornerPieces[4].LeadingEdge := IHM.PrLeadingEdgeX;
				CreationPiece_Corner.State := 160;
		END_IF

	160: //Linha 5
		IF NOT IHM.CreationCorner_MirrorCorner THEN
			PLC.CornerPieces[5].ZeroPieceX := PLC.CornerSquares[0].ZeroPieceX;
			PLC.CornerPieces[5].ZeroPieceY := PLC.CornerSquares[0].ZeroPieceY;
			IF NOT IHM.CreationCorner_ReverseCorner THEN
				PLC.CornerPieces[5].Width := PLC.CornerSquares[0].Width;
				PLC.CornerPieces[5].LastVertexAbsX := PLC.CornerSquares[0].ZeroPieceX + PLC.CornerSquares[0].Width;
				ELSIF IHM.CreationCorner_ReverseCorner THEN
					PLC.CornerPieces[5].Width := IHM.CreationCorner_X1;
					PLC.CornerPieces[5].LastVertexAbsX := PLC.CornerSquares[0].ZeroPieceX + IHM.CreationCorner_X1;
			END_IF
			PLC.CornerPieces[5].EntryEdge := IHM.PrEntryEdgeX;
			PLC.CornerPieces[5].LeadingEdge := IHM.PrLeadingEdgeX;
			CreationPiece_Corner.State := 170;
			ELSIF IHM.CreationCorner_MirrorCorner THEN
				PLC.CornerPieces[5].ZeroPieceX := PLC.CornerSquares[0].ZeroPieceX;
				PLC.CornerPieces[5].ZeroPieceY := PLC.CornerSquares[0].LastVertexAbsY + IHM.SawThickness;
				PLC.CornerPieces[5].Width := IHM.CreationCorner_X1;
				PLC.CornerPieces[5].LastVertexAbsX := PLC.CornerSquares[1].LastVertexAbsX;
				PLC.CornerPieces[5].EntryEdge := IHM.PrCornerEdgeX;
				PLC.CornerPieces[5].LeadingEdge := IHM.PrLeadingEdgeX;
				CreationPiece_Corner.State := 161;
		END_IF

	161: //Linha 6
		PLC.CornerPieces[6].ZeroPieceX := PLC.CornerSquares[2].ZeroPieceX;
		PLC.CornerPieces[6].ZeroPieceY := PLC.CornerSquares[1].ZeroPieceY;
		PLC.CornerPieces[6].Width := PLC.CornerSquares[1].Width;
		PLC.CornerPieces[6].LastVertexAbsX := PLC.CornerSquares[1].LastVertexAbsX;
		PLC.CornerPieces[6].EntryEdge := IHM.PrCornerEdgeX;
		PLC.CornerPieces[6].LeadingEdge := IHM.PrCornerEdgeX;
		CreationPiece_Corner.State := 162;

	162: //Linha 7
		PLC.CornerPieces[7].ZeroPieceX := PLC.CornerSquares[3].ZeroPieceX;
		PLC.CornerPieces[7].ZeroPieceY := PLC.CornerSquares[3].ZeroPieceY;
		PLC.CornerPieces[7].Width := IHM.CreationCorner_X1;
		PLC.CornerPieces[7].LastVertexAbsX := PLC.CornerSquares[3].LastVertexAbsX;
		PLC.CornerPieces[7].EntryEdge := IHM.PrCornerEdgeX;
		PLC.CornerPieces[7].LeadingEdge := IHM.PrCornerEdgeX;
		CreationPiece_Corner.State := 163;

	163: //Linha 8
		PLC.CornerPieces[8].ZeroPieceX := PLC.CornerSquares[0].ZeroPieceX;
		PLC.CornerPieces[5].ZeroPieceY := PLC.CornerSquares[0].ZeroPieceY;
		PLC.CornerPieces[8].Width := PLC.CornerSquares[0].Width;
		PLC.CornerPieces[8].LastVertexAbsX := PLC.CornerSquares[0].LastVertexAbsX;
		PLC.CornerPieces[8].EntryEdge := IHM.PrCornerEdgeX;
		PLC.CornerPieces[8].LeadingEdge := IHM.PrCornerEdgeX;
		CreationPiece_Corner.State := 170;

	170: //Reset bits de criação
		CreationPiece_CornerHalfDone := FALSE;
		IHM.CreationRectangle_MakeNewPieceSide := FALSE;
		IHM.CreationRectangle_MakeNewPieceDown := FALSE;
		IHM.CreationCorner_MakeCorner := FALSE;
		CreationPiece_Corner.State := 10;

	200: //Verifica se alguma peça foi criada, caso o banco de dados não possua dados a rotina será encerrada
		IF (PLC.CornerSquares[0].ZeroPieceX + PLC.CornerSquares[0].ZeroPieceY + PLC.CornerSquares[0].Width + PLC.CornerSquares[0].Height + PLC.CornerSquares[0].LastVertexAbsX + PLC.CornerSquares[0].LastVertexAbsY + TO_REAL(PLC.CornerSquares[0].EqualSerie)) = 0 THEN
			CreationPiece_Corner.State := 1000;
			ELSIF (PLC.CornerSquares[0].ZeroPieceX + PLC.CornerSquares[0].ZeroPieceY + PLC.CornerSquares[0].Width + PLC.CornerSquares[0].Height + PLC.CornerSquares[0].LastVertexAbsX + PLC.CornerSquares[0].LastVertexAbsY + TO_REAL(PLC.CornerSquares[0].EqualSerie)) > 0 THEN
				CreationPiece_Corner.State := 210;
		END_IF

	210: //Reseta bits de criação
		PLC.CornerDesigner_LastCornerArea := PLC.CornerArea - 1;
		CreationPiece_Corner.State := 1000;

	999: //Aborta rotina
		Creation_Abort();

	1000: //Finaliza rotina
		Creation_Done();
END_CASE

(*Inicia criação da peça*)
IF IHM.CreationForms_Start AND CreationPiece_Forms.State = 0 THEN
	CreationPiece_Forms.State := 1;
	CreationPiece_Forms.Start := TRUE;
	(*Cancela criação*)
	ELSIF IHM.CancelPiece AND CreationPiece_Forms.State <> 0 THEN
		CreationPiece_Forms.State := 999;
END_IF

(*Rotina de criação das peças em forma*)
CASE CreationPiece_Forms.State OF
	1: //Rotina rodando
		Creation_Running();

	2: //Reseta indexadores
		IHM.Figure := 0;
		PLC.Piece := 0;
		PLC.PieceFigure := 0;
		CreationPiece_Forms.State := 3;

	3: //Reseta variaveis das peças
		PLC.FormsSquare.ZeroPieceY := 0;
		PLC.FormsSquare.ZeroPieceX := 0;
		PLC.FormsSquare.Width := 0;
		PLC.FormsSquare.LastVertexAbsY := 0;
		PLC.FormsSquare.LastVertexAbsX := 0;
		PLC.FormsSquare.Height := 0;
		PLC.FormsCircle.ZeroPieceY := 0;
		PLC.FormsCircle.ZeroPieceX := 0;
		PLC.FormsCircle.Radius := 0;
		PLC.FormsCircle.Width := 0;
		PLC.FormsCircle.Height := 0;
		PLC.FormsHexagon.Apothem := 0;
		PLC.FormsHexagon.Perimeter := 0;
		PLC.FormsHexagon.PositionCenter[0] := 0;
		PLC.FormsHexagon.PositionCenter[1] := 0;
		PLC.FormsHexagon.ZeroPieceX := 0;
		PLC.FormsHexagon.ZeroPieceY := 0;
		PLC.FormsTriangle.Height := 0;
		PLC.FormsTriangle.Side := 0;
		PLC.FormsTriangle.ZeroPieceX := 0;
		PLC.FormsTriangle.ZeroPieceY := 0;
		CreationPiece_Forms.State := 10;

	10: //Identifica função selecionada pelo operador 
		IF IHM.CreationForms_MakeNewPiece AND PLC.Piece = 0 THEN
			CreationPiece_Forms.State := 20;
			ELSIF IHM.DeleteLastPiece AND PLC.Piece <> 0 THEN
				CreationPiece_Forms.State := 200;
				ELSIF IHM.FinishPiece THEN
					CreationPiece_Forms.State := 1000;
		END_IF

	20: //Verifica se alguma figura foi selecionada
		IF IHM.Figure = 0 THEN
			IHM.NoFigure := TRUE;
			CreationPiece_Forms.State := 22;
			ELSIF IHM.Figure <> 0 THEN
				CreationPiece_Forms.State := 21;
		END_IF

	21: //Verifica se a as posições não estão zeradas
		IF IHM.Figure = 1 THEN
			IF (IHM.NewWidth * IHM.NewHeight) = 0 THEN
				IHM.ZeroMessage := TRUE;
				CreationPiece_Forms.State := 23;
				ELSIF (IHM.NewWidth * IHM.NewHeight) <> 0 THEN
					CreationPiece_Forms.State := 24;
			END_IF
		END_IF

		IF IHM.Figure = 2 THEN
			IF (IHM.CreationForms_Width * IHM.CreationForms_Height * IHM.CreationForms_Radius) = 0 THEN
				IHM.ZeroMessage := TRUE;
				CreationPiece_Forms.State := 23;
				ELSIF (IHM.CreationForms_Width * IHM.CreationForms_Height * IHM.CreationForms_Radius) <> 0 THEN
					CreationPiece_Forms.State := 24;
			END_IF
		END_IF

		IF IHM.Figure = 3 THEN
			IF (IHM.CreationForms_Width * IHM.CreationForms_Height * IHM.CreationForms_Perimeter) = 0 THEN
				IHM.ZeroMessage := TRUE;
				CreationPiece_Forms.State := 23;
				ELSIF (IHM.CreationForms_Width * IHM.CreationForms_Height * IHM.CreationForms_Perimeter) <> 0 THEN
					CreationPiece_Forms.State := 24;
			END_IF
		END_IF

		IF IHM.Figure = 4 THEN
			IF IHM.NewHeight = 0 THEN
				IHM.ZeroMessage := TRUE;
				CreationPiece_Forms.State := 23;
				ELSIF IHM.NewHeight <> 0 THEN
					CreationPiece_Forms.State := 24;
			END_IF
		END_IF

	22: //Reseta bit de mensagem
		IF NOT IHM.NoFigure THEN
			IHM.CreationForms_MakeNewPiece :=  FALSE;
			CreationPiece_Forms.State := 10;
		END_IF

	23: //Reseta bit de mensagem
		IF NOT IHM.ZeroMessage THEN
			IHM.CreationForms_MakeNewPiece :=  FALSE;
			CreationPiece_Forms.State := 10;
		END_IF

	24: //Verifica qual peça foi selecionada
		IF IHM.Figure = 1 THEN
			CreationPiece_Forms.State := 30; //Quadrado/Retangulo
			ELSIF IHM.Figure = 2 THEN
				CreationPiece_Forms.State := 40; //Circulo
				ELSIF IHM.Figure = 3 THEN
					CreationPiece_Forms.State := 50; //Hexagono
					ELSIF IHM.Figure = 4 THEN
						CreationPiece_Forms.State := 60; //Triangulo
		END_IF

(*-----------------QUADRADO-----------------*)	

	30: //Atualiza zero peça X e Y da peça
		PLC.FormsSquare.ZeroPieceX := IHM.PrZeroPieceMachineX;
		PLC.FormsSquare.ZeroPieceY := IHM.PrZeroPieceMachineY;
		CreationPiece_Forms.State := 31;

	31: //Insere largura e altura da peça
		PLC.FormsSquare.Width := IHM.NewWidth;
		PLC.FormsSquare.Height := IHM.NewHeight;
		CreationPiece_Forms.State := 32;

	32: //Insere valores do ultimo vertice de X e Y
		PLC.FormsSquare.LastVertexAbsX := PLC.FormsSquare.ZeroPieceX + PLC.FormsSquare.Width;
		PLC.FormsSquare.LastVertexAbsY := PLC.FormsSquare.ZeroPieceY + PLC.FormsSquare.Height;
		CreationPiece_Forms.State := 33;

	33: //Série de tamanhos iguais recebe 1
		PLC.FormsSquare.EqualSerie := 1;
		CreationPiece_Forms.State := 34;

	34: //Cria imagem da peça
		CreationPiece_Forms.State := 35;

	35: //Soma no indexador
		PLC.Piece := PLC.Piece + 1;
		CreationPiece_Forms.State := 36;

	36: //Soma na quantidade de figuras
		PLC.PieceFigure := PLC.Piece;
		CreationPiece_Forms.State := 37;

	37: //Reseta bits de criação
		IHM.CreationForms_MakeNewPiece := FALSE;
		CreationPiece_Forms.State := 10;

(*-----------------CIRCULO-----------------*)	

	40: //Atualiza zero peça X e Y da peça
		PLC.FormsCircle.ZeroPieceX := IHM.PrZeroPieceMachineX;
		PLC.FormsCircle.ZeroPieceY := IHM.PrZeroPieceMachineY;
		CreationPiece_Forms.State := 41;

	41: //Insere posição do centro do circulo e raio do circulo
		PLC.FormsCircle.Width := IHM.CreationForms_Width;
		PLC.FormsCircle.Height := IHM.CreationForms_Height;
		PLC.FormsCircle.Radius := IHM.CreationForms_Radius;
		CreationPiece_Forms.State := 42;

	42: //Cria imagem da peça
		CreationPiece_Forms.State := 43;

	43: //Soma no indexador		
		PLC.Piece := PLC.Piece + 1;
		CreationPiece_Forms.State := 44;

	44: //Soma na quantidade de figuras
		PLC.PieceFigure := PLC.Piece;
		CreationPiece_Forms.State := 45;

	45: //Reseta bits de criação
		IHM.CreationForms_MakeNewPiece := FALSE;
		CreationPiece_Forms.State := 10;

(*-----------------HEXAGONO-----------------*)

	50: //Atualiza zero peça X e Y da peça
		PLC.FormsHexagon.ZeroPieceX := IHM.PrZeroPieceMachineX;
		PLC.FormsHexagon.ZeroPieceY := IHM.PrZeroPieceMachineY;
		CreationPiece_Forms.State := 51;

	51: //Insere posição do centro de haxagono
		PLC.FormsHexagon.PositionCenter[0] := IHM.CreationForms_Width;
		PLC.FormsHexagon.PositionCenter[1] := IHM.CreationForms_Height;
		CreationPiece_Forms.State := 52;

	52: //Insere valores de perimetro
		PLC.FormsHexagon.Perimeter := IHM.CreationForms_Perimeter;
		CreationPiece_Forms.State := 53;

	53: //Calcula apótema
		PLC.FormsHexagon.Apothem := TO_REAL((SQRT(3) / 2) * IHM.CreationForms_Perimeter);
		CreationPiece_Forms.State := 54;

	54: //Cria imagem da peça
		CreationPiece_Forms.State := 55;

	55: //Soma no indexador
		PLC.Piece := PLC.Piece + 1;
		CreationPiece_Forms.State := 56;

	56: //Soma na quantidade de figuras
		PLC.PieceFigure := PLC.Piece;
		CreationPiece_Forms.State := 57;

	57: //Reseta bits de operação
		IHM.CreationForms_MakeNewPiece := FALSE;
		CreationPiece_Forms.State := 10;

(*-----------------TRIANGULO-----------------*)

	60: //Atualiza zero peça X e Y da peça
		PLC.FormsTriangle.ZeroPieceX := IHM.PrZeroPieceMachineX;
		PLC.FormsTriangle.ZeroPieceY := IHM.PrZeroPieceMachineY;
		CreationPiece_Forms.State := 61;

	61: //Insere valor de altura
		PLC.FormsTriangle.Height := IHM.NewHeight;
		CreationPiece_Forms.State := 62;

	62: //Calcula os lados do triangulo
		PLC.FormsTriangle.Side := (2 * PLC.FormsTriangle.Height) / 3;
		CreationPiece_Forms.State := 63;

	63: //Cria imagem da peça
		CreationPiece_Forms.State := 64;

	64: //Soma no indexador
		PLC.Piece := PLC.Piece + 1;
		CreationPiece_Forms.State := 65;

	65: //Soma na quantidade de figuras
		PLC.PieceFigure := PLC.Piece;
		CreationPiece_Forms.State := 66;

	66: //Reseta bits de operação
		IHM.CreationForms_MakeNewPiece := FALSE;
		CreationPiece_Forms.State := 10;

	200: //Remove pontos da ultima peça
		IF IHM.Figure = 1 THEN
			PLC.FormsSquare.ZeroPieceY := 0;
			PLC.FormsSquare.ZeroPieceX := 0;
			PLC.FormsSquare.Width := 0;
			PLC.FormsSquare.LastVertexAbsY := 0;
			PLC.FormsSquare.LastVertexAbsX := 0;
			PLC.FormsSquare.Height := 0;
			CreationPiece_Forms.State := 201;
			ELSIF IHM.Figure = 2 THEN
				PLC.FormsCircle.ZeroPieceY := 0;
				PLC.FormsCircle.ZeroPieceX := 0;
				PLC.FormsCircle.Radius := 0;
				PLC.FormsCircle.Width := 0;
				PLC.FormsCircle.Height := 0;
				CreationPiece_Forms.State := 201;
				ELSIF IHM.Figure = 3 THEN
					PLC.FormsHexagon.Apothem := 0;
					PLC.FormsHexagon.Perimeter := 0;
					PLC.FormsHexagon.PositionCenter[0] := 0;
					PLC.FormsHexagon.PositionCenter[1] := 0;
					PLC.FormsHexagon.ZeroPieceX := 0;
					PLC.FormsHexagon.ZeroPieceY := 0;
					CreationPiece_Forms.State := 201;
					ELSIF IHM.Figure = 4 THEN
						PLC.FormsTriangle.Height := 0;
						PLC.FormsTriangle.Side := 0;
						PLC.FormsTriangle.ZeroPieceX := 0;
						PLC.FormsTriangle.ZeroPieceY := 0;
						CreationPiece_Forms.State := 201;
		END_IF

	201: //Subtrai indexador
		PLC.Piece := PLC.Piece - 1;
		CreationPiece_Forms.State := 202;

	202: //Subtrai quantidade de figuras
		PLC.PieceFigure := PLC.Piece;
		CreationPiece_Forms.State := 203;

	203: //Reseta bits de operação
		IHM.CreationForms_MakeNewPiece := FALSE;
		IHM.DeleteLastPiece := FALSE;
		CreationPiece_Forms.State := 10;

	999: //Abortar rotina
		Creation_Abort();

	1000: //Rotina finalizada
		Creation_Done();
END_CASE

(*Condição para habilitar modo automático*)
IF PLC.Machine = States.Manual THEN
	IF IHM.btStart OR PLC.IO.Start THEN
		Auto.Start := TRUE;
		PLC.Machine := States.Automatic;
		Auto.State := 1;
	END_IF
	(*Condição para parar processo*)
	ELSIF PLC.Machine = States.Automatic THEN
		IF IHM.btStop OR PLC.IO.Stop OR PLC.Axis[1].Error OR PLC.Axis[2].Error OR PLC.Axis[3].Error OR PLC.Axis[4].Error THEN
			Auto.State := 999;
		END_IF
END_IF

(*Rotina de corte retangular*)
CASE Auto.State OF
	1: //Estado rodando
		Automatic_Running();

	2: //Reseta variaveis
		PLC.CutPiece := 0;
		PLC.CuttingTable90_Step := 0;
		AutomaticRectangle_TotalHeightDisplacement := 0;
		AutomaticRectangle_TotalWidthDisplacement := 0;
		Auto.State := 10;

	10: //Posição fora da peça
		PLC.Axis[3].OperationDistance := IHM.PrOutsidePiece;
		PLC.IO.SawSpin := TRUE;
		PLC.Axis[3].OperationAbsolute := TRUE;
		Auto.State := 11;

	11: //Movimenta eixo Z
		PLC.Axis[3].OperationStart := TRUE;
		IF NOT PLC.Axis[3].OperationDone THEN
			Auto.State := 12;
		END_IF

	12: //Aguarda movimentação do eixo
		IF PLC.Axis[3].OperationDone THEN
			PLC.Axis[3].OperationStart := FALSE;
			Auto.State := 20;
		END_IF

	20: //Serra 90° ou 0° + Serra Ligada
		IF NOT IHM.CutMode THEN
			PLC.Axis[4].OperationDistance := 90;
			Auto.State := 21;
			ELSIF IHM.CutMode THEN
				PLC.Axis[4].OperationDistance := 0;
				Auto.State := 21;
		END_IF

	21: //Movimenta eixo W
		PLC.Axis[4].OperationStart := TRUE;
		IF NOT PLC.Axis[4].OperationDone THEN
			Auto.State := 22;
		END_IF

	22: //Aguarda movimentação do eixo
		IF PLC.Axis[4].OperationDone THEN
			PLC.Axis[4].OperationStart := FALSE;
			Auto.State := 30;
		END_IF

	30: //Posicão Zero Peça X + Zero Peça Y (descontando borda de entrada) da peça indexada
		IF NOT IHM.CutMode THEN
			PLC.Axis[1].OperationDistance := PLC.RectangularPieces[PLC.CutPiece].ZeroPieceX;
			PLC.Axis[2].OperationDistance := PLC.RectangularPieces[PLC.CutPiece].ZeroPieceY + IHM.PrEntryEdgeY;
			Auto.State := 40;
			PLC.Axis[1].OperationAbsolute := TRUE;
			PLC.Axis[2].OperationAbsolute := TRUE;
			//Posicão Zero Peça X (descontando borda de entrada) + Zero Peça Y da peça indexada
			ELSIF IHM.CutMode THEN
				PLC.Axis[1].OperationDistance := PLC.RectangularPieces[PLC.CutPiece].LastVertexAbsX + (IHM.PrEntryEdgeX * -1);
				PLC.Axis[2].OperationDistance := PLC.RectangularPieces[PLC.CutPiece].ZeroPieceY;
				Auto.State := 40;
				PLC.Axis[1].OperationAbsolute := TRUE;
				PLC.Axis[2].OperationAbsolute := TRUE;
		END_IF

	31: //SEGUNDO CORTE ÚLTIMA PEÇA EIXO Y - Posicão Último Vértice Absoluto X (acrescentando espessura da serra) + Zero Peça Y (descontando borda de entrada) da peça indexada
		IF NOT IHM.CutMode THEN
			PLC.Axis[1].OperationDistance := PLC.RectangularPieces[PLC.CutPiece].LastVertexAbsX + IHM.SawThickness;
			PLC.Axis[2].OperationDistance := PLC.RectangularPieces[PLC.CutPiece].ZeroPieceY + IHM.PrEntryEdgeY;
			Auto.State := 40;
			PLC.Axis[1].OperationAbsolute := TRUE;
			PLC.Axis[2].OperationAbsolute := TRUE;
			//SEGUNDO CORTE ÚLTIMA PEÇA EIXO X - Posicão Último Vértice Absoluto X (descontando borda de entrada) + Zero Peça Y (acrescentando espessura da serra) da peça indexada
			ELSIF IHM.CutMode THEN
				PLC.Axis[1].OperationDistance := PLC.RectangularPieces[PLC.CutPiece].LastVertexAbsX + (IHM.PrEntryEdgeX * -1);
				PLC.Axis[2].OperationDistance := PLC.RectangularPieces[PLC.CutPiece].LastVertexAbsY + IHM.SawThickness;
				Auto.State := 40;
				PLC.Axis[1].OperationAbsolute := TRUE;
				PLC.Axis[2].OperationAbsolute := TRUE;
		END_IF

	40: //Movimenta eixo X
		PLC.Axis[1].OperationStart := TRUE;
		IF NOT PLC.Axis[1].OperationDone THEN
			Auto.State := 41;
		END_IF

	41: //Movimenta eixo Y
		PLC.Axis[2].OperationStart := TRUE;
		IF NOT PLC.Axis[2].OperationDone THEN
			Auto.State := 42;
		END_IF

	42: //Aguarda sensor da serra 90° ou 0° e as movimentações de X e Y
		IF NOT (IHM.CutMode AND PLC.Axis[4].Position = 90) OR (IHM.CutMode AND PLC.Axis[4].Position = 0) THEN
			IF PLC.Axis[1].OperationDone AND PLC.Axis[2].OperationDone THEN
				PLC.Axis[1].OperationStart := FALSE;
				PLC.Axis[2].OperationStart := FALSE;
				Auto.State := 50;
			END_IF
		END_IF

	50: //Posição dentro da peça
		PLC.Axis[3].OperationDistance := IHM.PrInsidePiece;
		Auto.State := 60;
		PLC.Axis[3].OperationAbsolute := TRUE;

	60: //Movimenta eixo Z
		PLC.Axis[3].OperationStart := TRUE;
		IF NOT PLC.Axis[3].OperationDone THEN
			Auto.State := 61;
		END_IF

	61: //Aguarda movimentação do eixo 
		IF PLC.Axis[3].OperationDone THEN
			PLC.Axis[3].OperationStart := FALSE;
			Auto.State := 70;
		END_IF

	70: //Deslocamento da altura (descontando bordas de entrada e saída) da peça indexada
		IF NOT IHM.CutMode THEN
			PLC.Axis[2].OperationDistance := PLC.RectangularPieces[PLC.CutPiece].Height + (IHM.PrEntryEdgeY * -1) + (IHM.PrLeadingEdgeY * -1);
			Auto.State := 80;
			PLC.Axis[2].OperationAbsolute := FALSE;
			ELSIF IHM.CutMode THEN
				PLC.Axis[1].OperationDistance := (PLC.RectangularPieces[PLC.CutPiece].Width * -1) + IHM.PrEntryEdgeX + IHM.PrLeadingEdgeX;
				Auto.State := 80;
				PLC.Axis[1].OperationAbsolute := FALSE;
		END_IF

	80: //Movimenta eixo X ou Y
		IF NOT IHM.CutMode THEN
			PLC.Axis[2].OperationStart := TRUE;
			IF NOT PLC.Axis[2].OperationDone THEN
				Auto.State := 81;
			END_IF
			ELSIF IHM.CutMode THEN
				PLC.Axis[1].OperationStart := TRUE;
				IF NOT PLC.Axis[1].OperationDone THEN
					Auto.State := 81;
				END_IF
		END_IF

	81: //Aguarda movimentação X ou Y
		IF NOT IHM.CutMode THEN
			IF PLC.Axis[2].OperationDone THEN
				PLC.Axis[2].OperationStart := FALSE;
				Auto.State := 90;
			END_IF
			ELSIF IHM.CutMode THEN
				IF PLC.Axis[1].OperationDone THEN
					PLC.Axis[1].OperationStart := FALSE;
					Auto.State := 90;
				END_IF
		END_IF

	90: //Posição fora da peça
		PLC.Axis[3].OperationDistance := IHM.PrOutsidePiece;
		Auto.State := 100;
		PLC.Axis[3].OperationAbsolute := TRUE;

	100: //Movimenta eixo Z
		PLC.Axis[3].OperationStart := TRUE;
		IF NOT PLC.Axis[3].OperationDone THEN
			Auto.State := 101;
		END_IF

	101: //Aguardando movimentação do eixo
		IF PLC.Axis[3].OperationDone THEN
			PLC.Axis[3].OperationStart := FALSE;
			Auto.State := 110;
		END_IF

	110: //Verifica se a peça indexada é a última criada
		IF AutomaticRectangle_SecondCutLastPiece AND (PLC.CutPiece = PLC.LastPiece) THEN
			Auto.State := 119;
			ELSIF PLC.CutPiece <> PLC.LastPiece THEN
				Auto.State := 111;
				ELSIF NOT AutomaticRectangle_SecondCutLastPiece AND (PLC.CutPiece = PLC.LastPiece) THEN
					AutomaticRectangle_SecondCutLastPiece := TRUE;
					Auto.State := 31;
		END_IF

	111: //Passa para próxima peça
		PLC.CutPiece := PLC.CutPiece + 1;
		Auto.State := 30;

(*LOOP DE CORTES DINÂMICOS EIXO X, ÚLTIMA PEÇA ATÉ PEÇA 0 COM AVISO DE RETIRADA DE PEÇA*)

	119: //Serra 90° ou 0°
		IF NOT IHM.CutMode THEN
			PLC.Axis[4].OperationDistance := 0;
			Auto.State := 120;
			ELSIF IHM.CutMode THEN
				PLC.Axis[4].OperationDistance := 90;
				Auto.State := 120;
		END_IF

	120: //Movimenta eixo W
		PLC.Axis[4].OperationStart := TRUE;
		IF NOT PLC.Axis[4].OperationDone THEN
			Auto.State := 121;
		END_IF

	121: //Aguarda movimentação do eixo
		IF PLC.Axis[4].OperationDone THEN
			PLC.Axis[4].OperationStart := FALSE;
			Auto.State := 122;
		END_IF

	122: //CORTE GERAL EIXO X - Posicão Último Vértice X (descontando borda de entrada) + Zero Peça Y da peça indexada
		IF NOT IHM.CutMode THEN
			PLC.Axis[1].OperationDistance := PLC.RectangularPieces[PLC.CutPiece].LastVertexAbsX + (IHM.PrEntryEdgeX * -1);
			PLC.Axis[2].OperationDistance := PLC.RectangularPieces[PLC.CutPiece].ZeroPieceY;
			Auto.State := 130;
			PLC.Axis[1].OperationAbsolute := TRUE;
			PLC.Axis[2].OperationAbsolute := TRUE;
			ELSIF IHM.CutMode THEN
				PLC.Axis[1].OperationDistance := PLC.RectangularPieces[PLC.CutPiece].ZeroPieceX;
				PLC.Axis[2].OperationDistance := PLC.RectangularPieces[0].ZeroPieceY + IHM.PrEntryEdgeY;
				Auto.State := 130;
				PLC.Axis[1].OperationAbsolute := TRUE;
				PLC.Axis[2].OperationAbsolute := TRUE;
		END_IF

	123: //CORTES DINÂMICOS EIXO X - Posicão Último Vértice Absoluto X (descontando borda de entrada) + Zero Peça Y (acrescentando espessura da serra) da peça indexada
		IF NOT IHM.CutMode THEN
			PLC.Axis[1].OperationDistance := PLC.RectangularPieces[PLC.CutPiece].LastVertexAbsX + (IHM.PrEntryEdgeX * -1);
			PLC.Axis[2].OperationDistance := PLC.RectangularPieces[PLC.CutPiece].LastVertexAbsY + IHM.SawThickness;
			Auto.State := 130;
			PLC.Axis[1].OperationAbsolute := TRUE;
			PLC.Axis[2].OperationAbsolute := TRUE;
			ELSIF IHM.CutMode THEN
				PLC.Axis[1].OperationDistance := PLC.RectangularPieces[PLC.CutPiece].LastVertexAbsX + IHM.SawThickness;
				PLC.Axis[2].OperationDistance := PLC.RectangularPieces[PLC.CutPiece-PLC.RectangularPieces[PLC.CutPiece].EqualSerie+1].ZeroPieceY + IHM.PrEntryEdgeY;
				Auto.State := 130;
				PLC.Axis[1].OperationAbsolute := TRUE;
				PLC.Axis[2].OperationAbsolute := TRUE;
		END_IF

	130: //Movimenta eixo X
		PLC.Axis[1].OperationStart := TRUE;
		IF NOT PLC.Axis[1].OperationDone THEN
			Auto.State := 131;
		END_IF

	131: //Movimenta eixo Y
		PLC.Axis[2].OperationStart := TRUE;
		IF NOT PLC.Axis[2].OperationDone THEN
			Auto.State := 132;
		END_IF

	132: //Aguarda sensor serra 90°/0° e movimentações dos eixos X e Y
		IF NOT IHM.CutMode AND (PLC.Axis[4].Position = 0) THEN
			IF PLC.Axis[1].OperationDone AND PLC.Axis[2].OperationDone THEN
				PLC.Axis[1].OperationStart := FALSE;
				PLC.Axis[2].OperationStart := FALSE;
				Auto.State := 140;
			END_IF
			ELSIF IHM.CutMode AND (PLC.Axis[4].Position = 90) THEN
				IF PLC.Axis[1].OperationDone AND PLC.Axis[2].OperationDone THEN
					PLC.Axis[1].OperationStart := FALSE;
					PLC.Axis[2].OperationStart := FALSE;
					Auto.State := 140;
				END_IF
		END_IF

	140: //Posição dentro da peça
		IF NOT PLC.CuttingPause THEN
			PLC.Axis[3].OperationDistance := IHM.PrInsidePiece;
			Auto.State := 150;
			PLC.Axis[3].OperationAbsolute := TRUE;
			ELSIF PLC.CuttingPause THEN
				IHM.PauseMessage := TRUE;
				PLC.Axis[3].OperationDistance := IHM.PrInsidePiece;
				Auto.State := 150;
				PLC.Axis[3].OperationAbsolute := TRUE;
		END_IF

	150: //Movimenta eixo Z
		IF NOT PLC.CuttingPause THEN
			PLC.Axis[3].OperationStart := TRUE;
			IF NOT PLC.Axis[3].OperationDone THEN
				Auto.State := 151;
			END_IF
			ELSIF PLC.CuttingPause AND IHM.ContinueOperation THEN
				PLC.CuttingPause := FALSE;
				PLC.Axis[3].OperationStart := TRUE;
				IF NOT PLC.Axis[3].OperationDone THEN
				Auto.State := 151;
				END_IF
		END_IF

	151: //Aguarda movimentação do eixo
		IF PLC.Axis[3].OperationDone THEN
			PLC.Axis[3].OperationStart := FALSE;
			Auto.State := 160;
		END_IF

	160: //Verifica se o próximo deslocamento é o geral fixo ou os dinâmicos
		IF NOT AutomaticRectangle_GeralCutOk THEN
			Auto.State := 191;
			ELSIF AutomaticRectangle_GeralCutOk THEN
				IF NOT IHM.CutMode THEN
					AutomaticRectangle_TotalWidthDisplacement := 0;
					Auto.State := 170;
					ELSIF IHM.CutMode THEN
						AutomaticRectangle_TotalHeightDisplacement := 0;
						Auto.State := 170;
				END_IF
		END_IF

	170: //Verifica alturas/larguras em série
		IF PLC.RectangularPieces[PLC.CutPiece].EqualSerie = 1 THEN
			Auto.State := 180;
			ELSIF PLC.RectangularPieces[PLC.CutPiece].EqualSerie <> 1 THEN
				Auto.State := 171;
		END_IF

	171: //Soma largura da peça (acrescentando a espessura da serra que fica entre elas)
		IF NOT IHM.CutMode THEN
			AutomaticRectangle_TotalWidthDisplacement := AutomaticRectangle_TotalWidthDisplacement + PLC.RectangularPieces[PLC.CutPiece].Width + IHM.SawThickness;
			Auto.State := 172;
			//Soma altura da peça (acrescentando a espessura da serra que fica entre elas)
			ELSIF IHM.CutMode THEN
				AutomaticRectangle_TotalHeightDisplacement := AutomaticRectangle_TotalHeightDisplacement + PLC.RectangularPieces[PLC.CutPiece].Height + IHM.SawThickness;
				Auto.State := 172;
		END_IF

	172: //Passa Para Peça Anterior
		PLC.CutPiece := PLC.CutPiece - 1;
		Auto.State := 170;

	180: //Soma largura da última peça da sequência
		IF NOT IHM.CutMode THEN
			AutomaticRectangle_TotalWidthDisplacement := AutomaticRectangle_TotalWidthDisplacement + PLC.RectangularPieces[PLC.CutPiece].Width;
			Auto.State := 190;
			//Soma altura da última peça da sequência
			ELSIF IHM.CutMode THEN
				AutomaticRectangle_TotalHeightDisplacement := AutomaticRectangle_TotalHeightDisplacement + PLC.RectangularPieces[PLC.CutPiece].Height;
				Auto.State := 190;
		END_IF

	190: //Deslocamento da largura (descontando bordas de entrada e saída) da peça indexada
		IF NOT IHM.CutMode THEN
			PLC.Axis[1].OperationDistance := (AutomaticRectangle_TotalWidthDisplacement * -1) + IHM.PrEntryEdgeX + IHM.PrLeadingEdgeX;
			Auto.State := 200;
			PLC.Axis[1].OperationAbsolute := FALSE;
			//Deslocamento da altura (descontando bordas de entrada e saída) da peça indexada
			ELSIF IHM.CutMode THEN
				PLC.Axis[2].OperationDistance := AutomaticRectangle_TotalHeightDisplacement + (IHM.PrEntryEdgeY * -1) + (IHM.PrLeadingEdgeY * -1);
				Auto.State := 200;
				PLC.Axis[2].OperationAbsolute := FALSE;
		END_IF

	191: //Deslocamento da largura (descontando bordas de entrada e saída) da peça indexada
		IF NOT IHM.CutMode THEN
			PLC.Axis[1].OperationDistance := (PLC.RectangularPieces[PLC.CutPiece].LastVertexAbsX * -1) + PLC.RectangularPieces[0].ZeroPieceX + IHM.PrEntryEdgeX + IHM.PrLeadingEdgeX;
			Auto.State := 200;
			PLC.Axis[1].OperationAbsolute := FALSE;
			ELSIF IHM.CutMode THEN
				PLC.Axis[2].OperationDistance := PLC.RectangularPieces[PLC.CutPiece].LastVertexAbsY + (PLC.RectangularPieces[0].ZeroPieceY * -1) + (IHM.PrEntryEdgeY * -1) + (IHM.PrLeadingEdgeY * -1);
				Auto.State := 200;
				PLC.Axis[2].OperationAbsolute := FALSE;
		END_IF

	200: //Movimenta eixo X ou Y
		IF NOT IHM.CutMode THEN
			PLC.Axis[1].OperationStart := TRUE;
			IF NOT PLC.Axis[1].OperationDone THEN
				Auto.State := 201;
			END_IF
			ELSIF IHM.CutMode THEN
				PLC.Axis[2].OperationStart := TRUE;
				IF NOT PLC.Axis[2].OperationDone THEN
					Auto.State := 201;
				END_IF
		END_IF

	201: //Aguarda movimentação X ou Y
		IF NOT IHM.CutMode AND PLC.Axis[1].OperationDone THEN
			PLC.Axis[1].OperationStart := FALSE;
			Auto.State := 210;
			ELSIF IHM.CutMode AND PLC.Axis[2].OperationDone THEN
				PLC.Axis[2].OperationStart := FALSE;
				Auto.State := 210;
		END_IF

	210: //Posição fora da peça
		PLC.Axis[3].OperationDistance := IHM.PrOutsidePiece;
		Auto.State := 220;
		PLC.Axis[3].OperationAbsolute := TRUE;

	220: //Movimenta eixo Z
		PLC.Axis[3].OperationStart := TRUE;
		IF NOT PLC.Axis[3].OperationDone THEN
			Auto.State := 221;
		END_IF

	221: //Aguarda movimentação do eixo
		IF PLC.Axis[3].OperationDone THEN
			PLC.Axis[3].OperationStart := FALSE;
			Auto.State := 230;
		END_IF

	230: //Verifica se a peça indexada é a primeira criada
		IF AutomaticRectangle_GeralCutOk AND PLC.CutPiece = 0 THEN
			Auto.State := 1000;
			ELSIF AutomaticRectangle_GeralCutOk AND PLC.CutPiece <> 0 THEN
				Auto.State := 231;
				ELSIF NOT AutomaticRectangle_GeralCutOk THEN
					AutomaticRectangle_GeralCutOk := TRUE;
					Auto.State := 123;
		END_IF

	231: //Passa Para Peça Anterior + Mensagem Corte Finalizado
		PLC.CutPiece := PLC.CutPiece - 1;
		PLC.CuttingPause := TRUE;
		Auto.State := 123;

	999: //Abortar rotina
		Automatic_Abort();

	1000: //Rotina finalizada
		Automatic_Done();
END_CASE

(*Condição para habilitar modo automático*)
IF PLC.Machine = States.Manual THEN
	IF IHM.btStart OR PLC.IO.Start THEN
		Auto.Start := TRUE;
		PLC.Machine := States.Automatic;
		Auto.State := 1;
	END_IF
	(*Condição para parar processo*)
	ELSIF PLC.Machine = States.Automatic THEN
		IF IHM.btStop OR PLC.IO.Stop OR PLC.Axis[1].Error OR PLC.Axis[2].Error OR PLC.Axis[3].Error OR PLC.Axis[4].Error THEN
			Auto.State := 999;
		END_IF
END_IF

(*Rotina de corte ortogonal*)
CASE Auto.State OF
	1: //Estado rodando
		Automatic_Running();

	2: //Reseta Variaveis
		PLC.CutLine := 0;
		PLC.GridTable_Step := 0;
		Auto.State := 3;

	3: //Recebe valor da primeira linha do eixo da largura
		IF NOT IHM.CutMode THEN
			PLC.CutLine := 21;
			Auto.State := 10;
			ELSIF IHM.CutMode THEN
				PLC.CutLine := 0;
				Auto.State := 10;
		END_IF

	10: //Posição Fora Peça
		PLC.Axis[3].OperationDistance := IHM.PrOutsidePiece;
		PLC.Axis[3].OperationAbsolute := TRUE;
		Auto.State := 11;

	11: //Movimenta eixo Z
		PLC.Axis[3].OperationStart := TRUE;
		IF NOT PLC.Axis[3].OperationDone THEN
			Auto.State := 12;
		END_IF

	12: //Aguarda movimentação do eixo
		IF PLC.Axis[3].OperationDone THEN
			PLC.Axis[3].OperationStart := FALSE;
			Auto.State := 20;
		END_IF

	20: //Serra 90° ou 0° + serra ligada
		IF NOT IHM.CutMode THEN
			PLC.Axis[4].OperationDistance := 90;
			Auto.State := 21;
			ELSIF IHM.CutMode THEN
				PLC.Axis[4].OperationDistance := 0;
				Auto.State := 21;
		END_IF

	21: //Movimenta eixo W
		PLC.Axis[4].OperationStart := TRUE;
		IF NOT PLC.Axis[4].OperationDone THEN
			Auto.State := 22;
		END_IF

	22: //Aguarda movimentação do eixo
		IF PLC.Axis[4].OperationDone THEN
			PLC.Axis[4].OperationStart := FALSE;
			Auto.State := 30;
		END_IF

	30: //Posicão Zero Peça X + Zero Peça Y (descontando borda de entrada) da peça indexada
		IF NOT IHM.CutMode THEN
			PLC.Axis[1].OperationDistance := PLC.OrthogonalPieces[PLC.CutLine].ZeroPieceX;
			PLC.Axis[2].OperationDistance := PLC.OrthogonalPieces[PLC.CutLine].ZeroPieceY + IHM.PrEntryEdgeY;
			PLC.Axis[1].OperationAbsolute := TRUE;
			PLC.Axis[2].OperationAbsolute := TRUE;
			Auto.State := 40;
			ELSIF IHM.CutMode THEN
				PLC.Axis[1].OperationDistance := PLC.OrthogonalPieces[PLC.CutLine].LastVertexAbsX + (IHM.PrEntryEdgeX * -1);
				PLC.Axis[2].OperationDistance := PLC.OrthogonalPieces[PLC.CutLine].ZeroPieceY;
				PLC.Axis[1].OperationAbsolute := TRUE;
				PLC.Axis[2].OperationAbsolute := TRUE;
				Auto.State := 40;
		END_IF

	40: //Movimenta eixo X
		PLC.Axis[1].OperationStart := TRUE;
		IF NOT PLC.Axis[1].OperationDone THEN
			Auto.State := 41;
		END_IF

	41: //Movimenta eixo y
		PLC.Axis[2].OperationStart := TRUE;
		IF NOT PLC.Axis[2].OperationDone THEN
			Auto.State := 42;
		END_IF

	42: //Aguarda serra 90° ou 0° e movimentações de X e Y
		IF NOT IHM.CutMode AND PLC.Axis[4].Position = 90 OR IHM.CutMode AND PLC.Axis[4].Position = 0 THEN
			IF PLC.Axis[1].OperationDone AND PLC.Axis[2].OperationDone THEN
				PLC.Axis[1].OperationStart := FALSE;
				PLC.Axis[2].OperationStart := FALSE;
				Auto.State := 50;
			END_IF
		END_IF

	50: //Posição dentro da peça
		PLC.Axis[3].OperationDistance := IHM.PrInsidePiece;
		PLC.Axis[3].OperationAbsolute := TRUE;
		Auto.State := 60;

	60: //Movimenta eixo Z
		PLC.Axis[3].OperationStart := TRUE;
		IF NOT PLC.Axis[3].OperationDone THEN
			Auto.State := 61;
		END_IF

	61: //Aguarda movimentação do eixo
		IF PLC.Axis[3].OperationDone THEN
			PLC.Axis[3].OperationStart := FALSE;
			Auto.State := 70;
		END_IF

	70: //Deslocamento da altura (descontando bordas de entrada e saída) da peça indexada
		IF NOT IHM.CutMode THEN
			PLC.Axis[2].OperationDistance := PLC.OrthogonalPieces[PLC.CutLine].Lenght + (IHM.PrEntryEdgeY * -1) + (IHM.PrLeadingEdgeY * -1);
			PLC.Axis[2].OperationAbsolute := FALSE;
			Auto.State := 80;
			ELSIF IHM.CutMode THEN
				PLC.Axis[1].OperationDistance := (PLC.OrthogonalPieces[PLC.CutLine].Lenght * -1) + IHM.PrEntryEdgeX + IHM.PrLeadingEdgeX;
				PLC.Axis[1].OperationAbsolute := FALSE;
				Auto.State := 80;
		END_IF

	80: //Movimenta eixo X ou Y
		IF NOT IHM.CutMode THEN
			PLC.Axis[2].OperationStart := TRUE;
			IF NOT PLC.Axis[2].OperationDone THEN
				Auto.State := 81;
			END_IF
			ELSIF IHM.CutMode THEN
				PLC.Axis[1].OperationStart := TRUE;
				IF NOT PLC.Axis[1].OperationDone THEN
					Auto.State := 81;
				END_IF
		END_IF

	81: //Aguarda movimentação X ou Y
		IF NOT IHM.CutMode AND PLC.Axis[2].OperationDone THEN
			PLC.Axis[2].OperationStart := FALSE;
			Auto.State := 90;
			ELSIF IHM.CutMode AND PLC.Axis[1].OperationDone THEN
				PLC.Axis[1].OperationStart := FALSE;
				Auto.State := 90;
		END_IF

	90: //Posição fora de peça
		PLC.Axis[3].OperationDistance := IHM.PrOutsidePiece;
		PLC.Axis[3].OperationAbsolute := TRUE;
		Auto.State := 100;

	100: //Movimenta eixo Z
		PLC.Axis[3].OperationStart := TRUE;
		IF NOT PLC.Axis[3].OperationDone THEN
			Auto.State := 101;
		END_IF

	101: //Aguarda movimentação do eixo
		IF PLC.Axis[3].OperationDone THEN
			PLC.Axis[3].OperationStart := FALSE;
			Auto.State := 110;
		END_IF

	110: //Verifica se a reta indexada é a última criada
		IF NOT IHM.CutMode THEN
			IF PLC.CutLine = PLC.Grid THEN
				Auto.State := 118;
				ELSIF PLC.CutLine <> PLC.Grid THEN
					Auto.State := 111;
			END_IF
			ELSIF IHM.CutMode THEN
				IF PLC.CutLine = PLC.GridDesigner_LastLine THEN
					Auto.State := 118;
					ELSIF PLC.CutLine <> PLC.GridDesigner_LastLine THEN
						Auto.State := 111;
				END_IF
		END_IF

	111: //Passa para próxima reta
		PLC.CutLine := PLC.CutLine + 1;
		Auto.State := 30;

	118: //Recebe valor da última reta do eixo da altura ou primeira reta do eixo da largura
		IF NOT IHM.CutMode THEN
			PLC.CutLine := PLC.GridDesigner_LastLine;
			Auto.State := 119;
			ELSIF IHM.CutMode THEN
				PLC.CutLine := 21;
				Auto.State := 119;
		END_IF

	119: //Serra 90° ou 0° + Serra Ligada
		IF NOT IHM.CutMode THEN
			PLC.Axis[4].OperationDistance := 0;
			Auto.State := 120;
			ELSIF IHM.CutMode THEN
				PLC.Axis[4].OperationDistance := 90;
				Auto.State := 120;
		END_IF

	120: //Movimenta eixo W
		PLC.Axis[4].OperationStart := TRUE;
		IF NOT PLC.Axis[4].OperationDone THEN
			Auto.State := 121;
		END_IF

	121: //Aguarda movimentação do eixo
		IF PLC.Axis[4].OperationDone THEN
			PLC.Axis[4].OperationStart := FALSE;
			Auto.State := 122;
		END_IF

	122: //Posicão Zero Peça X (descontando borda de entrada) + Zero Peça Y da peça indexada
		IF NOT IHM.CutMode THEN
			PLC.Axis[1].OperationDistance := PLC.OrthogonalPieces[PLC.CutLine].LastVertexAbsX + (IHM.PrEntryEdgeX * -1);
			PLC.Axis[2].OperationDistance := PLC.OrthogonalPieces[PLC.CutLine].ZeroPieceY;
			PLC.Axis[1].OperationAbsolute := TRUE;
			PLC.Axis[2].OperationAbsolute := TRUE;
			Auto.State := 130;
			ELSIF IHM.CutMode THEN
				PLC.Axis[1].OperationDistance := PLC.OrthogonalPieces[PLC.CutLine].ZeroPieceX;
				PLC.Axis[2].OperationDistance := PLC.OrthogonalPieces[PLC.CutLine].ZeroPieceY + IHM.PrEntryEdgeY;
				PLC.Axis[1].OperationAbsolute := TRUE;
				PLC.Axis[2].OperationAbsolute := TRUE;
				Auto.State := 130;
		END_IF

	130: //Movimenta eixo X
		PLC.Axis[1].OperationStart := TRUE;
		IF NOT PLC.Axis[1].OperationDone THEN
			Auto.State := 131;
		END_IF

	131: //Movimenta eixo Y
		PLC.Axis[2].OperationStart := TRUE;
		IF NOT PLC.Axis[2].OperationDone THEN
			Auto.State := 132;
		END_IF

	132: //Aguarda movimento 90°/0° e movimentações de X e Y
		IF NOT IHM.CutMode AND PLC.Axis[4].Position = 0 OR IHM.CutMode AND PLC.Axis[4].Position = 90 THEN
			IF PLC.Axis[1].OperationDone AND PLC.Axis[2].OperationDone THEN
				PLC.Axis[1].OperationStart := FALSE;
				PLC.Axis[2].OperationStart := FALSE;
				Auto.State := 140;
			END_IF
		END_IF

	140: //Posição dentro da peça
		PLC.Axis[3].OperationDistance := IHM.PrInsidePiece;
		PLC.Axis[3].OperationAbsolute := TRUE;
		Auto.State := 150;

	150: //Movimenta eixo Z
		PLC.Axis[3].OperationStart := TRUE;
		IF NOT PLC.Axis[3].OperationDone THEN
			Auto.State := 151;
		END_IF

	151: //Aguarda movimentação do eixo
		IF PLC.Axis[3].OperationDone THEN
			PLC.Axis[3].OperationStart := FALSE;
			Auto.State := 160;
		END_IF

	160: //Deslocamento da largura (descontando bordas de entrada e saída) da peça indexada
		IF NOT IHM.CutMode THEN
			PLC.Axis[1].OperationDistance := (PLC.OrthogonalPieces[PLC.CutLine].Lenght * -1) + IHM.PrEntryEdgeX + IHM.PrLeadingEdgeX;
			PLC.Axis[1].OperationAbsolute := FALSE;
			Auto.State := 170;
			ELSIF IHM.CutMode THEN
				PLC.Axis[2].OperationDistance := PLC.OrthogonalPieces[PLC.CutLine].Lenght + (IHM.PrEntryEdgeY * -1) + (IHM.PrLeadingEdgeY * -1);
				PLC.Axis[2].OperationAbsolute := FALSE;
				Auto.State := 170;
		END_IF

	170: //Movimenta X ou Y
		IF NOT IHM.CutMode THEN
			PLC.Axis[1].OperationStart := TRUE;
			IF NOT PLC.Axis[1].OperationDone THEN
				Auto.State := 171;
			END_IF
			ELSIF IHM.CutMode THEN
				PLC.Axis[2].OperationStart := TRUE;
				IF NOT PLC.Axis[2].OperationDone THEN
					Auto.State := 171;
				END_IF
		END_IF

	171: //Aguarda movimentação X ou Y
		IF NOT IHM.CutMode AND PLC.Axis[1].OperationDone THEN
			PLC.Axis[1].OperationStart := FALSE;
			Auto.State := 180;
			ELSIF IHM.CutMode AND PLC.Axis[2].OperationDone THEN
				PLC.Axis[2].OperationStart := FALSE;
				Auto.State := 180;
		END_IF

	180: //Posição fora da peça
		PLC.Axis[3].OperationDistance := IHM.PrOutsidePiece;
		PLC.Axis[3].OperationAbsolute := TRUE;
		Auto.State := 190;

	190: //Movimenta eixo Z
		PLC.Axis[3].OperationStart := TRUE;
		IF NOT PLC.Axis[3].OperationDone THEN
			Auto.State := 191;
		END_IF

	191: //Aguarda movimentação do eixo
		IF PLC.Axis[3].OperationDone THEN
			PLC.Axis[3].OperationStart := FALSE;
			Auto.State := 200;
		END_IF

	200: //Verifica se a reta indexada é a primeira
		IF NOT IHM.CutMode THEN
			IF PLC.CutLine = 0 THEN
				Auto.State := 1000;
				ELSIF PLC.CutLine <> 0 THEN
					Auto.State := 201;
			END_IF
			ELSIF IHM.CutMode THEN
				IF PLC.CutLine = PLC.Grid THEN
					Auto.State := 1000;
					ELSIF PLC.CutLine <> PLC.Grid THEN
						Auto.State := 202;
				END_IF
		END_IF

	201: //Passa para reta anterior
		PLC.CutLine := PLC.CutLine - 1;
		Auto.State := 122;

	202: //Passa para reta peça
		PLC.CutLine := PLC.CutLine + 1;
		Auto.State := 122;

	999: //Abortar rotina
		Automatic_Abort();

	1000: //Finalizar rotina
		Automatic_Done();
END_CASE

(*Condição para habilitar modo automático*)
IF PLC.Machine = States.Manual THEN
	IF IHM.btStart OR PLC.IO.Start THEN
		Auto.Start := TRUE;
		PLC.Machine := States.Automatic;
		Auto.State := 1;
	END_IF
	(*Condição para parar processo*)
	ELSIF PLC.Machine = States.Automatic THEN
		IF IHM.btStop OR PLC.IO.Stop OR PLC.Axis[1].Error OR PLC.Axis[2].Error OR PLC.Axis[3].Error OR PLC.Axis[4].Error THEN
			Auto.State := 999;
		END_IF
END_IF

(*Rotina de corte corner [L]*)
CASE Auto.State OF
	1: //Estado rodando
		Automatic_Running();

	2: //Reseta variaveis
		AutomaticCorner_Reverse := FALSE;
		PLC.CutStraight := 0;
		AutomaticCorner_CuttingStep := 0;
		Auto.State := 10;

	10: //Posição fora da peça
		PLC.Axis[3].OperationDistance := IHM.PrOutsidePiece;
		PLC.IO.SawSpin := TRUE;
		PLC.Axis[3].OperationAbsolute := TRUE;
		Auto.State := 11;

	11: //Movimenta eixo Z
		PLC.Axis[3].OperationStart := TRUE;
		IF NOT PLC.Axis[3].OperationDone THEN
			Auto.State := 12;
		END_IF

	12: //Aguarda movimntação do eixo
		IF PLC.Axis[3].OperationDone THEN
			PLC.Axis[3].OperationStart := FALSE;
			Auto.State := 20;
		END_IF

	20: //Serra 90°
		PLC.Axis[4].OperationDistance := 90;
		Auto.State := 21;

	21: //Movimenta eixo W
		PLC.Axis[4].OperationStart := TRUE;
		IF NOT PLC.Axis[4].OperationDone THEN
			Auto.State := 22;
		END_IF

	22: //Aguarda movimentação do eixo
		IF PLC.Axis[4].OperationDone THEN
			PLC.Axis[4].OperationStart := FALSE;
			Auto.State := 30;
		END_IF

	30: //Posicão Zero Peça X + Zero Peça Y (descontando borda de entrada) da peça indexada
		IF NOT AutomaticCorner_HorizontalCutting THEN
			PLC.Axis[1].OperationDistance := PLC.CornerPieces[PLC.CutStraight].ZeroPieceX;
			PLC.Axis[2].OperationDistance := PLC.CornerPieces[PLC.CutStraight].ZeroPieceY + PLC.CornerPieces[PLC.CutStraight].EntryEdge;
			PLC.Axis[1].OperationAbsolute := TRUE;
			PLC.Axis[2].OperationAbsolute := TRUE;
			Auto.State := 40;
			ELSIF AutomaticCorner_HorizontalCutting THEN
				PLC.Axis[1].OperationDistance := PLC.CornerPieces[PLC.CutStraight].LastVertexAbsX + (PLC.CornerPieces[PLC.CutStraight].EntryEdge * -1);
				PLC.Axis[2].OperationDistance := PLC.CornerPieces[PLC.CutStraight].ZeroPieceY;
				PLC.Axis[1].OperationAbsolute := TRUE;
				PLC.Axis[2].OperationAbsolute := TRUE;
				Auto.State := 40;
		END_IF

	40: //Movimenta eixo X
		PLC.Axis[1].OperationStart := TRUE;
		IF NOT PLC.Axis[1].OperationDone THEN
			Auto.State := 41;
		END_IF

	41: //Movimenta eixo Y
		PLC.Axis[2].OperationStart := TRUE;
		IF NOT PLC.Axis[2].OperationDone THEN
			Auto.State := 42;
		END_IF

	42: //Aguardaserra 90° ou 0° e movimentações do eixo X e Y
		IF (NOT AutomaticCorner_HorizontalCutting AND PLC.Axis[4].Position = 90 AND PLC.Axis[1].OperationDone AND PLC.Axis[2].OperationDone) OR (AutomaticCorner_HorizontalCutting AND PLC.Axis[4].Position = 90 AND PLC.Axis[1].OperationDone AND PLC.Axis[2].OperationDone) THEN
			PLC.Axis[1].OperationStart := FALSE;
			PLC.Axis[2].OperationStart := FALSE;
			Auto.State := 50;
		END_IF

	50: //Posição dentro da peça
		PLC.Axis[3].OperationDistance := IHM.PrInsidePiece;
		PLC.Axis[3].OperationAbsolute := TRUE;
		Auto.State := 60;

	60: //Movimenta eixo Z
		PLC.Axis[3].OperationStart := TRUE;
		IF NOT PLC.Axis[3].OperationDone THEN
			Auto.State := 61;
		END_IF

	61: //Aguarda movimentação do eixo
		IF PLC.Axis[3].OperationDone THEN
			PLC.Axis[3].OperationStart := FALSE;
			Auto.State := 70;
		END_IF

	70: //Deslocamento da altura (descontando bordas de entrada e saída) da peça indexada
		IF NOT AutomaticCorner_HorizontalCutting THEN
			PLC.Axis[2].OperationDistance := PLC.CornerPieces[PLC.CutStraight].Height + (PLC.CornerPieces[PLC.CutStraight].EntryEdge * -1) + (PLC.CornerPieces[PLC.CutStraight].LeadingEdge * -1);
			PLC.Axis[2].OperationAbsolute := FALSE;
			Auto.State := 80;
			ELSIF AutomaticCorner_HorizontalCutting THEN
				PLC.Axis[1].OperationDistance := (PLC.CornerPieces[PLC.CutStraight].Width * -1) + PLC.CornerPieces[PLC.CutStraight].EntryEdge + PLC.CornerPieces[PLC.CutStraight].LeadingEdge;
				PLC.Axis[1].OperationAbsolute := FALSE;
				Auto.State := 80;
		END_IF

	80: //Movimenta eixo X ou Y
		IF NOT AutomaticCorner_HorizontalCutting THEN
			PLC.Axis[2].OperationStart := TRUE;
			IF NOT PLC.Axis[2].OperationDone THEN
				Auto.State := 81;
			END_IF
			ELSIF AutomaticCorner_HorizontalCutting THEN
				PLC.Axis[1].OperationStart := TRUE;
				IF NOT PLC.Axis[1].OperationDone THEN
					Auto.State := 81;
				END_IF
		END_IF

	81: //Aguarda movimentação X ou Y
		IF NOT AutomaticCorner_HorizontalCutting AND PLC.Axis[2].OperationDone THEN
			PLC.Axis[2].OperationStart := FALSE;
			Auto.State := 90;
			ELSIF AutomaticCorner_HorizontalCutting AND PLC.Axis[1].OperationDone THEN
				PLC.Axis[1].OperationStart := FALSE;
				Auto.State := 90;
		END_IF

	90: //Posição fora de peça
		PLC.Axis[3].OperationDistance := IHM.PrOutsidePiece;
		PLC.Axis[3].OperationAbsolute := TRUE;
		Auto.State := 100;

	100: //Movimenta eixo Z
		PLC.Axis[3].OperationStart := TRUE;
		IF NOT PLC.Axis[3].OperationDone THEN
			Auto.State := 101;
		END_IF

	101: //Aguarda movimentação do eixo
		IF PLC.Axis[3].OperationDone THEN
			PLC.Axis[3].OperationStart := FALSE;
			Auto.State := 110;
		END_IF

	110: //Verifica espelhamento
		IF NOT IHM.CreationCorner_MirrorCorner THEN
			IF NOT AutomaticCorner_HorizontalCutting AND PLC.CutStraight = 2 THEN
				Auto.State := 111;
			END_IF
			IF (NOT AutomaticCorner_HorizontalCutting AND PLC.CutStraight <> 2) OR (AutomaticCorner_HorizontalCutting AND PLC.CutStraight <> 5) THEN
				Auto.State := 120;
			END_IF
			IF AutomaticCorner_HorizontalCutting AND PLC.CutStraight = 5 THEN
				Auto.State := 1000;
			END_IF
			ELSIF IHM.CreationCorner_MirrorCorner THEN
				IF NOT AutomaticCorner_HorizontalCutting AND PLC.CutStraight = 3 THEN
					Auto.State := 111;
				END_IF
				IF (NOT AutomaticCorner_HorizontalCutting AND PLC.CutStraight <> 3) OR (AutomaticCorner_HorizontalCutting AND PLC.CutStraight <> 8) THEN
					Auto.State := 120;
				END_IF
				IF AutomaticCorner_HorizontalCutting AND PLC.CutStraight = 8 THEN
					Auto.State := 1000;
				END_IF
		END_IF

	111: //Passa para próxima reta e gira serra para 0°
		AutomaticCorner_HorizontalCutting := TRUE;
		PLC.Axis[4].OperationDistance := 0;
		Auto.State := 112;

	112: //Movimenta eixo W
		PLC.Axis[4].OperationStart := TRUE;
		IF NOT PLC.Axis[4].OperationDone THEN
			Auto.State := 113;
		END_IF

	113: //Aguarda movimentação do eixo
		IF PLC.Axis[4].OperationDone THEN
			PLC.Axis[4].OperationStart := FALSE;
			Auto.State := 120;
		END_IF

	120: //Passa para próxima reta
		PLC.CutStraight := PLC.CutStraight + 1;
		Auto.State := 30;

	999: //Abortar rotina
		Automatic_Abort();

	1000: //Finaliza rotina
		Automatic_Done();
END_CASE

(*Condição para habilitar modo automático*)
IF PLC.Machine = States.Manual THEN
	IF IHM.btStart OR PLC.IO.Start THEN
		Auto.Start := TRUE;
		PLC.Machine := States.Automatic;
		Auto.State := 1;
	END_IF
	(*Condição para parar processo*)
	ELSIF PLC.Machine = States.Automatic THEN
		IF IHM.btStop OR PLC.IO.Stop OR PLC.Axis[1].Error OR PLC.Axis[2].Error OR PLC.Axis[3].Error OR PLC.Axis[4].Error THEN
			Auto.State := 999;
		END_IF
END_IF

(*Rotina de corte Formas*)
CASE Auto.State OF
	1: //Estado rodando
		Automatic_Running();

	2: //Reseta variaveis
		AutomaticForms_Segaments := 0;
		Auto.State := 10;

	10: //Posição fora da peça
		PLC.Axis[3].OperationDistance := IHM.PrOutsidePiece;
		PLC.Axis[3].OperationAbsolute := TRUE;
		PLC.IO.SawSpin := TRUE;
		Auto.State := 11;

	11: //Movimenta eixo Z
		PLC.Axis[3].OperationStart := TRUE;
		IF NOT PLC.Axis[3].OperationDone THEN
			Auto.State := 12;
		END_IF

	12: //Aguarda movimentação do eixo
		IF PLC.Axis[3].OperationDone THEN
			PLC.Axis[3].OperationStart := FALSE;
			Auto.State := 20;
		END_IF

	20: //Verifica qual figura foi selecionada
		IF IHM.Figure = 1 THEN
			Auto.State := 30; //Quadrado/Retangulo
			ELSIF IHM.Figure = 2 THEN
				Auto.State := 70; //Circulo
				ELSIF IHM.Figure = 3 THEN
					Auto.State := 50; //Hexagono
					ELSIF IHM.Figure = 4 THEN
						Auto.State := 60; //Triangulo
		END_IF

(*-----------------QUADRADO-----------------*)	

	30: //Gira serra 90°
		PLC.Axis[4].OperationDistance := 90;
		Auto.State := 31;

	31: //Movimenta eixo W
		PLC.Axis[4].OperationStart := TRUE;
		IF NOT PLC.Axis[4].OperationDone THEN
			Auto.State := 32;
		END_IF

	32: //Aguarda movimentação do eixo
		IF PLC.Axis[4].OperationDone THEN
			PLC.Axis[4].OperationStart := FALSE;
			Auto.State := 33;
		END_IF

	33: //Posição zero peça
		IF AutomaticForms_Segaments = 0 THEN
			PLC.Axis[1].OperationDistance := PLC.FormsSquare.ZeroPieceX;
			PLC.Axis[2].OperationDistance := PLC.FormsSquare.ZeroPieceY + IHM.PrEntryEdgeY;
			PLC.Axis[1].OperationAbsolute := TRUE;
			PLC.Axis[2].OperationAbsolute := TRUE;
			Auto.State := 34;
			ELSIF AutomaticForms_Segaments = 1 THEN
				PLC.Axis[1].OperationDistance := PLC.FormsSquare.LastVertexAbsX + IHM.SawThickness;
				PLC.Axis[2].OperationDistance := PLC.FormsSquare.ZeroPieceY + IHM.PrEntryEdgeY;
				PLC.Axis[1].OperationAbsolute := TRUE;
				PLC.Axis[2].OperationAbsolute := TRUE;
				Auto.State := 34;
		END_IF

	34: //Movimenta eixo X
		PLC.Axis[1].OperationStart := TRUE;
		IF NOT PLC.Axis[1].OperationDone THEN
			Auto.State := 35;
		END_IF

	35: //Movimenta eixo Y
		PLC.Axis[2].OperationStart := TRUE;
		IF NOT PLC.Axis[2].OperationDone THEN
			Auto.State := 36;
		END_IF

	36: //Aguarda movimento dos eixos e posição da serra 90°
		IF PLC.Axis[1].OperationDone AND PLC.Axis[2].OperationDone AND PLC.Axis[4].Position = 90 THEN
			PLC.Axis[1].OperationStart := FALSE;
			PLC.Axis[2].OperationStart := FALSE;
			Auto.State := 37;
		END_IF

	37: //Posição dentro da peça
		PLC.Axis[3].OperationDistance := IHM.PrInsidePiece;
		PLC.Axis[3].OperationAbsolute := TRUE;
		Auto.State := 38;

	38: //Movimenta eixo Z
		PLC.Axis[3].OperationStart := TRUE;
		IF NOT PLC.Axis[3].OperationDone THEN
			Auto.State := 39;
		END_IF

	39: //Aguarda movimentação do eixo
		IF PLC.Axis[3].OperationDone THEN
			PLC.Axis[3].OperationStart := FALSE;
			Auto.State := 40;
		END_IF

	40: //Deslocamento da altura
		PLC.Axis[2].OperationDistance := PLC.FormsSquare.Height + (IHM.PrEntryEdgeY * -1) + (IHM.PrLeadingEdgeY * -1);
		Auto.State := 41;

	41: //Movimenta eixo Y
		PLC.Axis[2].OperationStart := TRUE;
		IF NOT PLC.Axis[2].OperationDone THEN
			Auto.State := 42;
		END_IF

	42: //Aguarda movimento do eixo
		IF PLC.Axis[2].OperationDone THEN
			PLC.Axis[2].OperationStart := FALSE;
			Auto.State := 43;
		END_IF

	43: //Posição fora da peça
		PLC.Axis[3].OperationDistance := IHM.PrOutsidePiece;
		PLC.Axis[3].OperationAbsolute := TRUE;
		Auto.State := 44;

	44: //Movimento eixo Z
		PLC.Axis[3].OperationStart := TRUE;
		IF NOT PLC.Axis[3].OperationDone THEN
			Auto.State := 45;
		END_IF

	45: //Aguarda movimento do eixo
		IF PLC.Axis[3].OperationDone THEN
			PLC.Axis[3].OperationStart := FALSE;
			Auto.State := 46;
		END_IF

	46: //Soma na indexadora
		AutomaticForms_Segaments := AutomaticForms_Segaments + 1;
		Auto.State := 47;

	47: //Verifica se é o primeiro ou segundo corte
		IF AutomaticForms_Segaments = 2 THEN
			Auto.State := 48;
			ELSIF AutomaticForms_Segaments = 1 THEN
				Auto.State := 33;
		END_IF

	48: //Gira serra 0°
		PLC.Axis[4].OperationDistance := 0;
		Auto.State := 49;

	49: //Movimenta eixo W
		PLC.Axis[4].OperationStart := TRUE;
		IF NOT PLC.Axis[4].OperationDone THEN
			Auto.State := 50;
		END_IF

	50: //Aguarda movimentação do eixo
		IF PLC.Axis[4].OperationDone THEN
			PLC.Axis[4].OperationStart := FALSE;
			Auto.State := 51;
		END_IF

	51: //Posição zero peça
		IF AutomaticForms_Segaments = 2 THEN
			PLC.Axis[1].OperationDistance := PLC.FormsSquare.ZeroPieceX + IHM.PrEntryEdgeX;
			PLC.Axis[2].OperationDistance := PLC.FormsSquare.ZeroPieceY;
			Auto.State := 52;
			ELSIF AutomaticForms_Segaments = 3 THEN
				PLC.Axis[1].OperationDistance := PLC.FormsSquare.ZeroPieceX + IHM.PrEntryEdgeX;
				PLC.Axis[2].OperationDistance := PLC.FormsSquare.LastVertexAbsY + IHM.SawThickness;
				PLC.Axis[1].OperationAbsolute := TRUE;
				PLC.Axis[2].OperationAbsolute := TRUE;
				Auto.State := 52;
		END_IF

	52: //Movimenta eixo X
		PLC.Axis[1].OperationStart := TRUE;
		IF NOT PLC.Axis[1].OperationDone THEN
			Auto.State := 53;
		END_IF

	53: //Movimenta eixo Y
		PLC.Axis[2].OperationStart := TRUE;
		IF NOT PLC.Axis[2].OperationDone THEN
			Auto.State := 54;
		END_IF

	54: //Aguarda movimento dos eixos e posição da serra 0°
		IF PLC.Axis[1].OperationDone AND PLC.Axis[2].OperationDone AND PLC.Axis[4].Position = 0 THEN
			PLC.Axis[1].OperationStart := FALSE;
			PLC.Axis[2].OperationStart := FALSE;
			Auto.State := 55;
		END_IF

	55: //Posição dentro da peça
		PLC.Axis[3].OperationDistance := IHM.PrInsidePiece;
		PLC.Axis[3].OperationAbsolute := TRUE;
		Auto.State := 56;

	56: //Movimenta eixo Z
		PLC.Axis[3].OperationStart := TRUE;
		IF NOT PLC.Axis[3].OperationDone THEN
			Auto.State := 57;
		END_IF

	57: //Aguarda movimentação do eixo
		IF PLC.Axis[3].OperationDone THEN
			PLC.Axis[3].OperationStart := FALSE;
			Auto.State := 58;
		END_IF

	58: //Deslocamento da largura
		PLC.Axis[1].OperationDistance := PLC.FormsSquare.Width + (IHM.PrEntryEdgeX * -1) + (IHM.PrLeadingEdgeX * -1);
		Auto.State := 59;

	59: //Movimenta eixo Y
		PLC.Axis[1].OperationStart := TRUE;
		IF NOT PLC.Axis[1].OperationDone THEN
			Auto.State := 60;
		END_IF

	60: //Aguarda movimento do eixo
		IF PLC.Axis[1].OperationDone THEN
			PLC.Axis[1].OperationStart := FALSE;
			Auto.State := 61;
		END_IF

	61: //Posição fora da peça
		PLC.Axis[3].OperationDistance := IHM.PrOutsidePiece;
		PLC.Axis[3].OperationAbsolute := TRUE;
		Auto.State := 62;

	62: //Movimento eixo Z
		PLC.Axis[3].OperationStart := TRUE;
		IF NOT PLC.Axis[3].OperationDone THEN
			Auto.State := 63;
		END_IF

	63: //Aguarda movimento do eixo
		IF PLC.Axis[3].OperationDone THEN
			PLC.Axis[3].OperationStart := FALSE;
			Auto.State := 64;
		END_IF

	64: //Soma no indexador
		AutomaticForms_Segaments := AutomaticForms_Segaments + 1;
		Auto.State := 65;

	65: //Verifica se é o primeiro ou segundo corte
		IF AutomaticForms_Segaments = 4 THEN
			Auto.State := 1000;
			ELSIF AutomaticForms_Segaments = 3 THEN
				Auto.State := 51;
		END_IF

(*-----------------CIRCULO-----------------*)		

	70: //Gira serra 90°
		PLC.Axis[4].OperationDistance := 90;
		Auto.State := 71;

	71: //Movimenta eixo W
		PLC.Axis[4].OperationStart := TRUE;
		IF NOT PLC.Axis[4].OperationDone THEN
			Auto.State := 72;
		END_IF

	72: //Aguarda movimentação do eixo
		IF PLC.Axis[4].OperationDone THEN
			PLC.Axis[4].OperationStart := FALSE;
			Auto.State := 73;
		END_IF

	73: //Posição zero peça
		PLC.Axis[1].OperationDistance := PLC.FormsCircle.ZeroPieceX;
		PLC.Axis[2].OperationDistance := PLC.FormsCircle.Height / 2;
		PLC.Axis[1].OperationAbsolute := TRUE;
		PLC.Axis[2].OperationAbsolute := TRUE;
		Auto.State := 74;

	74: //Movimenta eixo X
		PLC.Axis[1].OperationStart := TRUE;
		IF NOT PLC.Axis[1].OperationDone THEN
			Auto.State := 75;
		END_IF

	75: //Movimenta eixo Y
		PLC.Axis[2].OperationStart := TRUE;
		IF NOT PLC.Axis[2].OperationDone THEN
			Auto.State := 76;
		END_IF

	76: //Aguarda movimento dos eixos e posição da serra 90°
		IF PLC.Axis[1].OperationDone AND PLC.Axis[2].OperationDone AND PLC.Axis[4].Position = 90 THEN
			PLC.Axis[1].OperationStart := FALSE;
			PLC.Axis[2].OperationStart := FALSE;
			Auto.State := 77;
		END_IF

	77: //Posição dentro da peça
		PLC.Axis[3].OperationDistance := IHM.PrInsidePiece;
		PLC.Axis[3].OperationAbsolute := TRUE;
		Auto.State := 78;

	78: //Movimenta eixo Z
		PLC.Axis[3].OperationStart := TRUE;
		IF NOT PLC.Axis[3].OperationDone THEN
			Auto.State := 79;
		END_IF

	79: //Aguarda movimentação do eixo
		IF PLC.Axis[3].OperationDone THEN
			PLC.Axis[3].OperationStart := FALSE;
			Auto.State := 80;
		END_IF

	80: //Primeira posição
		PLC.OperationAuxPos[0] := PLC.FormsCircle.Width / 2;
		PLC.OperationAuxPos[1] := PLC.FormsCircle.Height / 2;
		PLC.OperationEndPos[0] := PLC.FormsCircle.Width / 2;
		PLC.OperationEndPos[1] := PLC.FormsCircle.Height;
		Auto.State := 81;

	81: //Movimenta eixo X e Y
		PLC.OperationCirleStart := TRUE;
		IF NOT PLC.OperationCircleDone THEN
			Auto.State := 82;
		END_IF

	82: //Aguarda movimento
		IF PLC.OperationCircleDone THEN
			PLC.OperationCirleStart := FALSE;
			Auto.State := 83;
		END_IF

	83: //Segunda posição
		PLC.OperationAuxPos[0] := PLC.FormsCircle.Width / 2;
		PLC.OperationAuxPos[1] := PLC.FormsCircle.Height / 2;
		PLC.OperationEndPos[0] := PLC.FormsCircle.Width;
		PLC.OperationEndPos[1] := PLC.FormsCircle.Height / 2;
		Auto.State := 84;

	84: //Movimenta eixo X e Y
		PLC.OperationCirleStart := TRUE;
		IF NOT PLC.OperationCircleDone THEN
			Auto.State := 85;
		END_IF

	85: //Aguarda movimento
		IF PLC.OperationCircleDone THEN
			PLC.OperationCirleStart := FALSE;
			Auto.State := 86;
		END_IF

	86: //Terceira posição
		PLC.OperationAuxPos[0] := PLC.FormsCircle.Width / 2;
		PLC.OperationAuxPos[1] := PLC.FormsCircle.Height / 2;
		PLC.OperationEndPos[0] := PLC.FormsCircle.Width / 2;
		PLC.OperationEndPos[1] := PLC.FormsCircle.ZeroPieceY;
		Auto.State := 87;

	87: //Movimenta eixo X e Y
		PLC.OperationCirleStart := TRUE;
		IF NOT PLC.OperationCircleDone THEN
			Auto.State := 88;
		END_IF

	88: //Aguarda movimento
		IF PLC.OperationCircleDone THEN
			PLC.OperationCirleStart := FALSE;
			Auto.State := 89;
		END_IF

	89: //Quarta posição
		PLC.OperationAuxPos[0] := PLC.FormsCircle.Width / 2;
		PLC.OperationAuxPos[1] := PLC.FormsCircle.Height / 2;
		PLC.OperationEndPos[0] := PLC.FormsCircle.ZeroPieceX;
		PLC.OperationEndPos[1] := PLC.FormsCircle.Height / 2;
		Auto.State := 90;

	90: //Movimenta eixo X e Y
		PLC.OperationCirleStart := TRUE;
		IF NOT PLC.OperationCircleDone THEN
			Auto.State := 91;
		END_IF

	91: //Aguarda movimento
		IF PLC.OperationCircleDone THEN
			PLC.OperationCirleStart := FALSE;
			Auto.State := 92;
		END_IF

	92: //Posição fora da peça
		PLC.Axis[3].OperationDistance := IHM.PrOutsidePiece;
		PLC.Axis[3].OperationAbsolute := TRUE;
		Auto.State := 93;

	93: //Movimenta eixo Z
		PLC.Axis[3].OperationStart := TRUE;
		IF NOT PLC.Axis[3].OperationDone THEN
			Auto.State := 94;
		END_IF

	94: //Aguarda movimentação do eixo
		IF PLC.Axis[3].OperationDone THEN
			PLC.Axis[3].OperationStart := FALSE;
			Auto.State := 1000;
		END_IF

(*-----------------HEXAGONO-----------------*)	

	100:
		;

	999: //Abortar rotina
		Automatic_Abort();
END_CASE

(*Define novo ponto zero*)
FB_Setpoint[1](Axis := Axis1, Execute := Execute, Position := 0);
FB_Setpoint[2](Axis := Axis2, Execute := Execute, Position := 0);
FB_Setpoint[3](Axis := Axis3, Execute := Execute, Position := 0);

(*Condição para retornar para zero*)
IF Execute THEN
	//Posição para os eixos
	PLC.Axis[1].OperationDistance := 0;
	PLC.Axis[2].OperationDistance := 0;
	PLC.Axis[3].OperationDistance := 0;
	//Executa eixos
	PLC.Axis[1].OperationStart := TRUE;
	PLC.Axis[2].OperationStart := TRUE;
	PLC.Axis[3].OperationStart := TRUE;
	//Modo Absoluto
	PLC.Axis[1].OperationAbsolute := TRUE;
	PLC.Axis[2].OperationAbsolute := TRUE;
	PLC.Axis[3].OperationAbsolute := TRUE;
	(*Condição para finalizar retorno*)
	IF PLC.Axis[1].OperationDone AND PLC.Axis[2].OperationDone AND PLC.Axis[3].OperationDone THEN
		//Desabilita execução dos eixos
		PLC.Axis[1].OperationStart := FALSE;
		PLC.Axis[2].OperationStart := FALSE;
		PLC.Axis[3].OperationStart := FALSE;
		PLC.Axis[1].OperationAbsolute := FALSE;
		PLC.Axis[2].OperationAbsolute := FALSE;
		PLC.Axis[3].OperationAbsolute := FALSE;
		//Desabilita condição para retorno
		IHM.btGoToZero := FALSE;
	END_IF
	(*Condição para parar retorno*)
	IF IHM.btStop OR PLC.IO.Stop THEN
		//Desabilita execução dos eixos
		PLC.Axis[1].OperationStart := FALSE;
		PLC.Axis[2].OperationStart := FALSE;
		PLC.Axis[3].OperationStart := FALSE;
		PLC.Axis[1].OperationAbsolute := FALSE;
		PLC.Axis[2].OperationAbsolute := FALSE;
		PLC.Axis[3].OperationAbsolute := FALSE;
		//Desabilita condição para retorno
		IHM.btGoToZero := FALSE;
	END_IF
END_IF

(*Condição para girar a serra*)
IF Execute THEN
	//Posição para o eixo
	PLC.Axis[4].OperationDistance := IHM.RotateValue;
	//Executa eixos
	PLC.Axis[4].OperationStart := TRUE;
	(*Condição para finalizar função*)
	IF PLC.Axis[4].OperationDone THEN
		//Desabilita execução dos eixos
		PLC.Axis[4].OperationStart := FALSE;
		//Desabilita condição para retorno
		IHM.btRotateSaw := FALSE;
	END_IF
	(*Condição para parar retorno*)
	IF IHM.btStop OR PLC.IO.Stop THEN
		//Desabilita execução dos eixos
		PLC.Axis[4].OperationStart := FALSE;
		//Desabilita condição para retorno
		IHM.btRotateSaw := FALSE;
	END_IF
END_IF

IF Execute AND PLC.IO.SsMesaBaixa THEN
	PLC.IO.SobeMesa := TRUE;
	ELSE
		PLC.IO.SobeMesa := FALSE;
END_IF

IF Execute AND NOT PLC.IO.SsMesaBaixa THEN
	PLC.IO.DesceMesa := TRUE;
	ELSE
		PLC.IO.DesceMesa := FALSE;
END_IF

(*Informa erro nos eixos*)
FB_Error[1](Axis := Axis1, Enable := TRUE, AxisError => PLC.Axis[1].Error, AxisErrorID => PLC.Axis[1].ErrorID);
FB_Error[2](Axis := Axis2, Enable := TRUE, AxisError => PLC.Axis[2].Error, AxisErrorID => PLC.Axis[2].ErrorID);
FB_Error[3](Axis := Axis3, Enable := TRUE, AxisError => PLC.Axis[3].Error, AxisErrorID => PLC.Axis[3].ErrorID);
FB_Error[4](Axis := Axis4, Enable := TRUE, AxisError => PLC.Axis[4].Error, AxisErrorID => PLC.Axis[4].ErrorID);

(*Reseta eixos*)
FB_Reset[1](Axis := Axis1, Execute := IHM.btReset AND PLC.Axis[1].Error);
FB_Reset[2](Axis := Axis2, Execute := IHM.btReset AND PLC.Axis[2].Error);
FB_Reset[3](Axis := Axis3, Execute := IHM.btReset AND PLC.Axis[3].Error);
FB_Reset[4](Axis := Axis4, Execute := IHM.btReset AND PLC.Axis[4].Error);

(*Habilita eixos*)
FB_Power[1](Axis := Axis1, Enable := TRUE, bRegulatorOn := PLC.Safety_Enabled, bDriveStart := PLC.Safety_Enabled);
FB_Power[2](Axis := Axis2, Enable := TRUE, bRegulatorOn := PLC.Safety_Enabled, bDriveStart := PLC.Safety_Enabled);
FB_Power[3](Axis := Axis3, Enable := TRUE, bRegulatorOn := PLC.Safety_Enabled, bDriveStart := PLC.Safety_Enabled);
FB_Power[4](Axis := Axis4, Enable := TRUE, bRegulatorOn := PLC.Safety_Enabled, bDriveStart := PLC.Safety_Enabled);

(*Movimento absoluto para os eixos*) FB_Absolute[1]( //Eixo 1 Axis := Axis1, Execute := PLC.Axis[1].OperationStart, Position := PLC.Axis[1].OperationDistance, Velocity := PLC.Axis[1].OperationSpeed, Acceleration := PLC.Axis[1].Acceleration, Deceleration := PLC.Axis[1].Deceleration, Done => PLC.Axis[1].OperationDone);
FB_Absolute[2]( //Eixo 2 Axis := Axis2, Execute := PLC.Axis[2].OperationStart, Position := PLC.Axis[2].OperationDistance, Velocity := PLC.Axis[2].OperationSpeed, Acceleration := PLC.Axis[2].Acceleration, Deceleration := PLC.Axis[2].Deceleration, Done => PLC.Axis[2].OperationDone);
FB_Absolute[3]( //Eixo 3 Axis := Axis3, Execute := PLC.Axis[3].OperationStart, Position := PLC.Axis[3].OperationDistance, Velocity := PLC.Axis[3].OperationSpeed, Acceleration := PLC.Axis[3].Acceleration, Deceleration := PLC.Axis[3].Deceleration, Done => PLC.Axis[3].OperationDone);
FB_Absolute[4]( //Eixo 4 Axis := Axis4, Execute := PLC.Axis[4].OperationStart, Position := PLC.Axis[4].OperationDistance, Velocity := PLC.Axis[4].OperationSpeed, Acceleration := PLC.Axis[4].Acceleration, Deceleration := PLC.Axis[4].Deceleration, Done => PLC.Axis[4].OperationDone);

(*Homing dos eixos*) PLC.FB_Homing[1]( //Eixo 1 Axis := Axis1, fVelocitySlow := PLC.Axis[1].CreepSpeed, fVelocityFast := PLC.Axis[1].HomeSpeed, fAcceleration := PLC.Axis[1].Acceleration, fDeceleration := PLC.Axis[1].Deceleration, nDirection := PLC.Axis[1].HomeDirection, bReferenceSwitch := , nHomingMode := SMC_HOMING_MODE.FAST_BSLOW_STOP_S, bDone => PLC.Axis[1].HomeDone);
PLC.FB_Homing[2]( //Eixo 2 Axis := Axis2, fVelocitySlow := PLC.Axis[2].CreepSpeed, fVelocityFast := PLC.Axis[2].HomeSpeed, fAcceleration := PLC.Axis[2].Acceleration, fDeceleration := PLC.Axis[2].Deceleration, nDirection := PLC.Axis[2].HomeDirection, bReferenceSwitch := , nHomingMode := SMC_HOMING_MODE.FAST_BSLOW_STOP_S, bDone => PLC.Axis[2].HomeDone);
PLC.FB_Homing[3]( //Eixo 3 Axis := Axis3, fVelocitySlow := PLC.Axis[3].CreepSpeed, fVelocityFast := PLC.Axis[3].HomeSpeed, fAcceleration := PLC.Axis[3].Acceleration, fDeceleration := PLC.Axis[3].Deceleration, nDirection := PLC.Axis[3].HomeDirection, bReferenceSwitch := , nHomingMode := SMC_HOMING_MODE.FAST_BSLOW_STOP_S, bDone => PLC.Axis[3].HomeDone);
PLC.FB_Homing[4]( //Eixo 4 Axis := Axis4, fVelocitySlow := PLC.Axis[4].CreepSpeed, fVelocityFast := PLC.Axis[4].HomeSpeed, fAcceleration := PLC.Axis[4].Acceleration, fDeceleration := PLC.Axis[4].Deceleration, nDirection := PLC.Axis[4].HomeDirection, bReferenceSwitch := , nHomingMode := SMC_HOMING_MODE.FAST_BSLOW_STOP_S, bDone => PLC.Axis[4].HomeDone);

(*JOG dos eixos*) FB_Jog[1]( //Eixo 1 Axis := Axis1, JogForward := PLC.Axis[1].JogFwd, JogBackward := PLC.Axis[1].JogRev, Velocity := PLC.Axis[1].ManualSpeed, Acceleration := PLC.Axis[1].Acceleration, Deceleration := PLC.Axis[1].Deceleration);
FB_Jog[2]( //Eixo 2 Axis := Axis2, JogForward := PLC.Axis[2].JogFwd, JogBackward := PLC.Axis[2].JogRev, Velocity := PLC.Axis[2].ManualSpeed, Acceleration := PLC.Axis[2].Acceleration, Deceleration := PLC.Axis[2].Deceleration);
FB_Jog[3]( //Eixo 3 Axis := Axis3, JogForward := PLC.Axis[3].JogFwd, JogBackward := PLC.Axis[3].JogRev, Velocity := PLC.Axis[3].ManualSpeed, Acceleration := PLC.Axis[3].Acceleration, Deceleration := PLC.Axis[3].Deceleration);
FB_Jog[4]( //Eixo 4 Axis := Axis4, JogForward := PLC.Axis[4].JogFwd, JogBackward := PLC.Axis[4].JogRev, Velocity := PLC.Axis[4].ManualSpeed, Acceleration := PLC.Axis[4].Acceleration, Deceleration := PLC.Axis[4].Deceleration);

(*Posição dos eixos*) FB_Position[1]( //Eixo 1 Axis := Axis1, Enable := TRUE, Position => PLC.Axis[1].Position);
FB_Position[2]( //Eixo 2 Axis := Axis2, Enable := TRUE, Position => PLC.Axis[2].Position);
FB_Position[3]( //Eixo 3 Axis := Axis3, Enable := TRUE, Position => PLC.Axis[3].Position);
FB_Position[4]( //Eixo 4 Axis := Axis4, Enable := TRUE, Position => PLC.Axis[4].Position);

(*Stop dos eixos*) FB_Stop[1]( //Eixo 1 Axis := Axis1, Execute := PLC.Axis[1].Stop OR PLC.IO.Stop, Deceleration := PLC.Axis[1].Deceleration);
FB_Stop[2]( //Eixo 2 Axis := Axis2, Execute := PLC.Axis[2].Stop OR PLC.IO.Stop, Deceleration := PLC.Axis[2].Deceleration);
