FB_Stop[4]( //Eixo 4 Axis := Axis4, Execute := PLC.Axis[4].Stop OR PLC.IO.Stop, Deceleration := PLC.Axis[4].Deceleration);

(*Movimento absoluto para os eixos*) FB_Relative[1]( //Eixo 1 Axis := Axis1, Execute := PLC.Axis[1].OperationStart, Distance := PLC.Axis[1].OperationDistance, Velocity := PLC.Axis[1].OperationSpeed, Acceleration := PLC.Axis[1].Acceleration, Deceleration := PLC.Axis[1].Deceleration, Done => PLC.Axis[1].OperationDone);
FB_Relative[2]( //Eixo 2 Axis := Axis2, Execute := PLC.Axis[2].OperationStart, Distance := PLC.Axis[2].OperationDistance, Velocity := PLC.Axis[2].OperationSpeed, Acceleration := PLC.Axis[2].Acceleration, Deceleration := PLC.Axis[2].Deceleration, Done => PLC.Axis[2].OperationDone);
